                <input
                  type="number"
                  min="0"
                  value={amount}
                  onChange={e => setAmount(e.target.value)}
                  placeholder="0"
                  className="w-40 border-none bg-transparent p-0 text-left text-5xl font-black text-slate-800 placeholder-slate-200 focus:outline-none focus:ring-0"
                  style={{ MozAppearance: 'textfield' }}
                />
              </div>

              <div className="mb-6 flex justify-center text-green-500">
                <div className="flex items-center gap-1.5 text-[11px] font-bold tracking-wide">
                  <Lock size={12} />
                  <span>Amount {amount ? "locked" : "unlocked"} in QR</span>
