        await page.render({ canvasContext: ctx, viewport }).promise;
        thumbs[i - 1] = canvas.toDataURL("image/jpeg", 0.85);
      }
      setThumbnails(thumbs);
    } catch {
      toast.error("Failed to read PDF pages");
    } finally {
      setLoadingPreviews(false);
    }
  };

  const togglePageSelection = (pageIdx: number) => {
    setSelectedPages((prev) =>
      prev.includes(pageIdx) ? prev.filter((p) => p !== pageIdx) : [...prev, pageIdx].sort((a, b) => a - b)
    );
  };

  const selectAll = () => {
    setSelectedPages(Array.from({ length: totalPages }, (_, i) => i));
  };

  const deselectAll = () => {
    setSelectedPages([]);
  };

  const invertSelection = () => {
    setSelectedPages((prev) =>
      Array.from({ length: totalPages }, (_, i) => i).filter((i) => !prev.includes(i))
    );
  };

  // Parse page range input (e.g. "1-3, 5, 8-10")
  const parseRangeString = (str: string, maxPages: number): number[] => {
    const pagesSet = new Set<number>();
    const parts = str.split(",");
    for (const part of parts) {
      const trimmed = part.trim();
      if (!trimmed) continue;
      if (trimmed.includes("-")) {
        const [startStr, endStr] = trimmed.split("-");
        const start = parseInt(startStr, 10);
        const end = parseInt(endStr, 10);
        if (!isNaN(start) && !isNaN(end)) {
          const min = Math.max(1, Math.min(start, end));
          const max = Math.min(maxPages, Math.max(start, end));
          for (let i = min; i <= max; i++) {
            pagesSet.add(i - 1);
          }
        }
      } else {
        const val = parseInt(trimmed, 10);
        if (!isNaN(val) && val >= 1 && val <= maxPages) {
          pagesSet.add(val - 1);
        }
      }
    }
    return Array.from(pagesSet).sort((a, b) => a - b);
  };

  const handleSplit = async () => {
    if (!file) return;
    setLoading(true);

    try {
      const buf = await file.arrayBuffer();
      const srcDoc = await PDFDocument.load(buf, { ignoreEncryption: true });

      if (splitMode === "visual") {
        if (selectedPages.length === 0) {
          toast.error("Please select at least 1 page to extract");
          setLoading(false);
          return;
        }

        if (exportOption === "individual") {
          for (const pageIdx of selectedPages) {
            const newDoc = await PDFDocument.create();
            const [page] = await newDoc.copyPages(srcDoc, [pageIdx]);
            newDoc.addPage(page);
            const bytes = await newDoc.save();
            const blob = new Blob([new Uint8Array(bytes)], { type: "application/pdf" });
            const url = URL.createObjectURL(blob);
            downloadWithRename(url, `RA_Page_${pageIdx + 1}.pdf`);
          }
          toast.success(`Exported ${selectedPages.length} individual page PDFs!`);
        } else {
          const newDoc = await PDFDocument.create();
          const pages = await newDoc.copyPages(srcDoc, selectedPages);
          pages.forEach((p) => newDoc.addPage(p));
          const bytes = await newDoc.save();
          const blob = new Blob([new Uint8Array(bytes)], { type: "application/pdf" });
          const url = URL.createObjectURL(blob);
          downloadWithRename(url, `RA_Extracted_Pages.pdf`);
          toast.success(`Extracted ${selectedPages.length} pages into 1 merged PDF!`);
        }
      } else if (splitMode === "range") {
        const pagesToExtract = parseRangeString(rangeInput, totalPages);
        if (pagesToExtract.length === 0) {
          toast.error("Invalid page range entered. E.g. use '1-3, 5'");
          setLoading(false);
          return;
        }

        const newDoc = await PDFDocument.create();
        const pages = await newDoc.copyPages(srcDoc, pagesToExtract);
        pages.forEach((p) => newDoc.addPage(p));
        const bytes = await newDoc.save();
        const blob = new Blob([new Uint8Array(bytes)], { type: "application/pdf" });
        const url = URL.createObjectURL(blob);
        downloadWithRename(url, `RA_Split_Range.pdf`);
        toast.success(`Extracted range ${rangeInput} into PDF!`);
      } else if (splitMode === "every") {
        for (let i = 0; i < totalPages; i++) {
          const newDoc = await PDFDocument.create();
          const [page] = await newDoc.copyPages(srcDoc, [i]);
          newDoc.addPage(page);
          const bytes = await newDoc.save();
          const blob = new Blob([new Uint8Array(bytes)], { type: "application/pdf" });
          const url = URL.createObjectURL(blob);
          downloadWithRename(url, `RA_Page_${i + 1}.pdf`);
        }
        toast.success(`Split into ${totalPages} individual page PDFs!`);
      } else if (splitMode === "interval") {
        const numChunks = Math.ceil(totalPages / intervalPages);
        for (let c = 0; c < numChunks; c++) {
          const start = c * intervalPages;
          const end = Math.min(start + intervalPages, totalPages);
          const indices = Array.from({ length: end - start }, (_, i) => start + i);

          const newDoc = await PDFDocument.create();
          const pages = await newDoc.copyPages(srcDoc, indices);
          pages.forEach((p) => newDoc.addPage(p));
          const bytes = await newDoc.save();
          const blob = new Blob([new Uint8Array(bytes)], { type: "application/pdf" });
          const url = URL.createObjectURL(blob);
          downloadWithRename(url, `RA_Part_${c + 1}_P${start + 1}-${end}.pdf`);
        }
        toast.success(`Split into ${numChunks} PDF files (every ${intervalPages} pages)!`);
      }
    } catch {
      toast.error("Failed to split PDF file");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="space-y-6">
      {!file ? (
        <div
          onDrop={(e) => {
            e.preventDefault();
            setDragOver(false);
            if (e.dataTransfer.files[0]) handleFile(e.dataTransfer.files[0]);
          }}
          onDragOver={(e) => {
            e.preventDefault();
            setDragOver(true);
          }}
          onDragLeave={() => setDragOver(false)}
          onClick={() => inputRef.current?.click()}
          style={{
            backgroundColor: dragOver ? "#fff7ed" : "#ffffff",
            borderTop: "2px solid #808080",
            borderLeft: "2px solid #808080",
            borderRight: "2px solid #ffffff",
            borderBottom: "2px solid #ffffff",
            boxShadow: "inset 1px 1px 2px rgba(0,0,0,0.2)",
          }}
          className="p-10 text-center cursor-pointer transition-all hover:bg-orange-50/50 rounded-lg"
        >
          <Scissors size={40} className="mx-auto mb-3 text-orange-600" />
          <p className="text-lg font-black mb-1" style={{ color: "#000080" }}>
            Drop PDF here to see Visual Page Splitter
          </p>
          <p className="text-xs font-semibold text-slate-500">or click to browse PDF document</p>
          <input
            ref={inputRef}
            type="file"
            accept=".pdf,application/pdf"
            hidden
            onChange={(e) => e.target.files?.[0] && handleFile(e.target.files[0])}
          />
        </div>
      ) : (
        <div className="space-y-6 animate-fade-in">
          {/* File Overview Bar */}
          <div className="flex items-center justify-between gap-3 p-3 bg-white border border-slate-300 rounded-lg shadow-xs">
            <div className="flex items-center gap-3 min-w-0">
              <FileText size={28} className="text-red-600 shrink-0" />
              <div className="min-w-0">
                <p className="font-extrabold text-sm text-slate-900 truncate">{file.name}</p>
                <p className="text-xs font-semibold text-slate-500">
                  {formatFileSize(file.size)} • {totalPages} Total Pages
                </p>
              </div>
            </div>
            <button
              onClick={() => {
                setFile(null);
                setTotalPages(0);
              }}
              className="p-1.5 text-red-600 hover:bg-red-50 rounded border border-red-200 text-xs font-bold flex items-center gap-1 shrink-0"
            >
              <X size={16} /> Remove PDF
            </button>
          </div>

          {/* 4 Pro Split Modes Selection Tabs */}
          <div className="grid grid-cols-2 md:grid-cols-4 gap-2">
            {[
              { id: "visual", label: "🔲 Select Pages Visually", desc: "Click pages to pick" },
              { id: "range", label: "📏 Custom Range", desc: "e.g. 1-3, 5, 8" },
              { id: "every", label: "✂️ Split All Pages", desc: "Extract 1 by 1" },
              { id: "interval", label: "📊 Fixed Interval", desc: "Split every N pages" },
            ].map((m) => (
              <button
                key={m.id}
                type="button"
                onClick={() => setSplitMode(m.id as SplitMode)}
                style={{
                  backgroundColor: splitMode === m.id ? "#ea580c" : "#d4d0c8",
                  color: splitMode === m.id ? "#ffffff" : "#000000",
                  borderTop: "2px solid #ffffff",
                  borderLeft: "2px solid #ffffff",
                  borderRight: "2px solid #404040",
                  borderBottom: "2px solid #404040",
                }}
                className="p-2.5 text-left rounded cursor-pointer transition-all shadow-xs"
              >
                <div className="font-black text-xs">{m.label}</div>
                <div className="text-[10px] opacity-80 mt-0.5">{m.desc}</div>
              </button>
            ))}
          </div>

          {/* Mode 1: Interactive Visual Page Grid */}
          {splitMode === "visual" && (
            <div className="space-y-4">
              <div className="flex flex-wrap items-center justify-between gap-2 p-2.5 bg-slate-100 border border-slate-300 rounded-lg">
                <div className="flex items-center gap-2">
                  <span className="text-xs font-extrabold text-slate-800">
                    Selected {selectedPages.length} of {totalPages} pages
                  </span>
                </div>
                <div className="flex items-center gap-2">
                  <button
                    type="button"
                    onClick={selectAll}
                    className="px-2.5 py-1 text-xs font-bold bg-white hover:bg-slate-200 text-slate-800 rounded border border-slate-300"
                  >
                    Select All
                  </button>
                  <button
                    type="button"
                    onClick={deselectAll}
                    className="px-2.5 py-1 text-xs font-bold bg-white hover:bg-slate-200 text-slate-800 rounded border border-slate-300"
                  >
                    Deselect All
                  </button>
                  <button
                    type="button"
                    onClick={invertSelection}
                    className="px-2.5 py-1 text-xs font-bold bg-white hover:bg-slate-200 text-slate-800 rounded border border-slate-300"
                  >
                    Invert
                  </button>
                </div>
              </div>

              {/* Export Mode Toggle */}
              <div className="flex items-center gap-4 bg-orange-50/70 p-3 rounded-lg border border-orange-200 text-xs">
                <span className="font-bold text-orange-950">Export Selected Pages as:</span>
                <label className="flex items-center gap-1.5 font-bold cursor-pointer text-slate-800">
                  <input
                    type="radio"
                    name="exportOpt"
                    checked={exportOption === "merged"}
                    onChange={() => setExportOption("merged")}
                    className="accent-orange-600"
                  />
                  Single Merged PDF
                </label>
                <label className="flex items-center gap-1.5 font-bold cursor-pointer text-slate-800">
                  <input
                    type="radio"
                    name="exportOpt"
                    checked={exportOption === "individual"}
                    onChange={() => setExportOption("individual")}
                    className="accent-orange-600"
                  />
                  Individual Separate PDFs
                </label>
              </div>

              {/* Visual Page Thumbnails Grid */}
              <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 gap-3 max-h-[500px] overflow-y-auto p-1">
                {Array.from({ length: totalPages }, (_, idx) => {
                  const isSelected = selectedPages.includes(idx);
                  const thumb = thumbnails[idx];

                  return (
                    <div
                      key={idx}
                      onClick={() => togglePageSelection(idx)}
                      style={{
                        backgroundColor: isSelected ? "#fff7ed" : "#ffffff",
                        borderColor: isSelected ? "#ea580c" : "#cbd5e1",
                      }}
                      className={`relative p-2 rounded-lg border-2 cursor-pointer transition-all flex flex-col justify-between group ${
                        isSelected ? "shadow-md ring-2 ring-orange-500/20" : "opacity-80 hover:opacity-100 hover:border-slate-400"
                      }`}
                    >
                      {/* Checkbox badge */}
                      <div className="flex items-center justify-between gap-1 mb-1.5">
                        <span className={`text-[10px] font-black px-1.5 py-0.5 rounded ${
                          isSelected ? "bg-orange-600 text-white" : "bg-slate-200 text-slate-700"
                        }`}>
                          Page {idx + 1}
                        </span>
                        {isSelected ? (
                          <CheckSquare size={16} className="text-orange-600" />
                        ) : (
                          <Square size={16} className="text-slate-400" />
                        )}
                      </div>

                      {/* Thumbnail Image */}
                      <div className="relative bg-white border border-slate-200 rounded overflow-hidden min-h-[130px] flex items-center justify-center">
                        {loadingPreviews ? (
                          <Loader2 size={16} className="animate-spin text-orange-500" />
                        ) : thumb ? (
                          <img src={thumb} alt={`Page ${idx + 1}`} className="w-full h-full object-contain max-h-[140px] p-1" />
                        ) : (
                          <FileText size={28} className="text-slate-300" />
                        )}

                        <button
                          type="button"
                          onClick={(e) => {
                            e.stopPropagation();
                            setPreviewPageIndex(idx);
                          }}
                          className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center gap-1 text-white text-[11px] font-bold"
                        >
                          <Eye size={14} /> Zoom
                        </button>
                      </div>
                    </div>
                  );
                })}
              </div>
            </div>
          )}

          {/* Mode 2: Range Input */}
          {splitMode === "range" && (
            <div className="bg-white p-5 rounded-lg border border-slate-300 space-y-3">
              <label className="text-xs font-black text-slate-800 block">
                Enter Page Numbers / Ranges (e.g., "1-3, 5, 8-10"):
              </label>
              <input
                type="text"
                value={rangeInput}
                onChange={(e) => setRangeInput(e.target.value)}
                placeholder="e.g. 1-3, 5, 7-9"
                className="w-full p-2.5 text-base font-extrabold border border-slate-400 rounded outline-none focus:border-orange-500"
              />
              <p className="text-xs text-slate-500">
                Total available pages in this PDF: <strong className="text-slate-800">{totalPages} pages</strong>
              </p>
            </div>
          )}

          {/* Mode 3: Split Every Page */}
          {splitMode === "every" && (
            <div className="bg-orange-50 border border-orange-200 rounded-lg p-4 text-center">
              <p className="font-extrabold text-sm text-orange-900">
                ✂️ Will extract every page into {totalPages} separate individual 1-page PDF files.
              </p>
            </div>
          )}

          {/* Mode 4: Fixed Interval */}
          {splitMode === "interval" && (
            <div className="bg-white p-5 rounded-lg border border-slate-300 space-y-3">
              <label className="text-xs font-black text-slate-800 block">
                Split PDF every N pages:
              </label>
              <div className="flex items-center gap-3">
                <input
                  type="number"
                  min={1}
                  max={totalPages}
                  value={intervalPages}
                  onChange={(e) => setIntervalPages(Math.max(1, parseInt(e.target.value) || 1))}
                  className="w-32 p-2.5 text-xl font-extrabold text-center border border-slate-400 rounded"
                />
                <span className="text-xs font-bold text-slate-700">
                  Will create {Math.ceil(totalPages / intervalPages)} PDF files ({intervalPages} pages per file)
                </span>
              </div>
            </div>
          )}

          {/* Split Action Button */}
          <button
            onClick={handleSplit}
            disabled={loading}
            style={{
              backgroundColor: "#ea580c",
              color: "#ffffff",
              borderTop: "2px solid #ffffff",
              borderLeft: "2px solid #ffffff",
              borderRight: "2px solid #9a3412",
              borderBottom: "2px solid #9a3412",
            }}
            className="w-full py-3.5 text-base font-extrabold flex items-center justify-center gap-2 cursor-pointer hover:bg-orange-700 transition-colors shadow-md rounded"
          >
            {loading ? (
              <>
                <Loader2 size={20} className="animate-spin" /> Splitting PDF...
              </>
            ) : (
              <>
                <Scissors size={20} /> Execute Split PDF Now
              </>
            )}
          </button>
        </div>
      )}

      {/* Page Zoom Preview Modal */}
      {previewPageIndex !== null && (
        <div className="fixed inset-0 z-50 bg-black/60 backdrop-blur-xs flex items-center justify-center p-4 animate-in fade-in duration-200">
          <div
            style={{
              backgroundColor: "#d4d0c8",
              borderTop: "2px solid #ffffff",
              borderLeft: "2px solid #ffffff",
              borderRight: "2px solid #404040",
              borderBottom: "2px solid #404040",
            }}
            className="max-w-xl w-full p-2 rounded shadow-2xl flex flex-col max-h-[90vh]"
          >
            <div
              style={{
                background: "linear-gradient(to right, #000080 0%, #1084d0 100%)",
                color: "#ffffff",
              }}
              className="px-3 py-1.5 font-bold text-xs flex justify-between items-center"
            >
              <span>Page {previewPageIndex + 1} Preview</span>
              <button
                onClick={() => setPreviewPageIndex(null)}
                className="w-5 h-5 bg-red-600 text-white font-bold text-xs flex items-center justify-center rounded cursor-pointer"
              >
                ✕
              </button>
            </div>

            <div className="p-4 bg-white border border-slate-400 mt-1 overflow-y-auto flex flex-col items-center justify-center">
              {thumbnails[previewPageIndex] ? (
                <img
                  src={thumbnails[previewPageIndex]}
                  alt={`Page ${previewPageIndex + 1}`}
                  className="max-h-[65vh] w-auto object-contain border border-slate-300 shadow-md"
                />
              ) : (
                <div className="p-8 text-slate-500 text-xs">No preview</div>
              )}
            </div>

            <div className="mt-2 text-right">
              <button
                onClick={() => setPreviewPageIndex(null)}
                className="px-4 py-1 bg-slate-300 hover:bg-slate-400 font-bold text-xs rounded border border-slate-500"
              >
                Close
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import { useRef, useState } from "react";
import { PDFDocument } from "pdf-lib";
import { FileText, Loader2, X, Unlock, Eye, EyeOff, KeyRound, ShieldOff } from "lucide-react";
import { useToast } from "@/contexts/ToastContext";
import { useDownload } from "@/contexts/DownloadContext";

function formatSize(n: number) {
  return n > 1024 * 1024 ? `${(n / 1024 / 1024).toFixed(2)} MB` : `${Math.round(n / 1024)} KB`;
}

export default function UnlockPdfTool() {
  const toast = useToast();
  const { downloadWithRename } = useDownload();
  const [file, setFile] = useState<File | null>(null);
  const [password, setPassword] = useState("");
  const [showPw, setShowPw] = useState(false);
  const [loading, setLoading] = useState(false);
  const [dragOver, setDragOver] = useState(false);
  const [unlocked, setUnlocked] = useState(false);
  const inputRef = useRef<HTMLInputElement>(null);

  const handleFile = (incoming: File) => {
    if (!incoming.name.toLowerCase().endsWith(".pdf")) { toast.error("Please select a PDF file"); return; }
    setFile(incoming);
    setUnlocked(false);
    setPassword("");
  };

  const handleUnlock = async () => {
    if (!file) return;
    setLoading(true);
    try {
      const buf = await file.arrayBuffer();
      const doc = await PDFDocument.load(buf, {
        password: password || undefined,
        ignoreEncryption: !password
      } as any);
      const bytes = await doc.save();
      const blob = new Blob([new Uint8Array(bytes)], { type: "application/pdf" });
      const url = URL.createObjectURL(blob);
      downloadWithRename(url, `RA_Unlocked_${file.name}`);
      setUnlocked(true);
      toast.success("PDF unlocked and downloaded successfully!");
    } catch (e: any) {
      if (e?.message?.toLowerCase().includes("password")) {
        toast.error("Wrong password. Please try again.");
      } else {
        toast.error("Failed to unlock PDF. The file may not be password-protected or uses unsupported encryption.");
      }
    } finally { setLoading(false); }
  };

  return (
    <div className="space-y-5">
      {/* Info Banner */}
      <div className="p-3 bg-emerald-50 border border-emerald-200 rounded-lg text-xs text-emerald-800 font-semibold flex items-start gap-2">
        <ShieldOff size={16} className="shrink-0 mt-0.5 text-emerald-600" />
        <span>This tool strips PDF restrictions and removes known passwords using <strong>pdf-lib</strong>. If the PDF uses strong 256-bit AES encryption, it may require the correct password to unlock.</span>
      </div>

      {!file ? (
        <div
          onDrop={(e) => { e.preventDefault(); setDragOver(false); if (e.dataTransfer.files[0]) handleFile(e.dataTransfer.files[0]); }}
          onDragOver={(e) => { e.preventDefault(); setDragOver(true); }}
          onDragLeave={() => setDragOver(false)}
          onClick={() => inputRef.current?.click()}
          style={{
            backgroundColor: dragOver ? "#ecfdf5" : "#ffffff",
            borderTop: "2px solid #808080",
            borderLeft: "2px solid #808080",
            borderRight: "2px solid #ffffff",
            borderBottom: "2px solid #ffffff",
            boxShadow: "inset 1px 1px 2px rgba(0,0,0,0.2)",
          }}
          className="p-10 text-center cursor-pointer transition-all hover:bg-emerald-50/50 rounded-lg"
        >
          <Unlock size={40} className="mx-auto mb-3 text-emerald-500" />
          <p className="text-lg font-black mb-1" style={{ color: "#000080" }}>Drop Password-Protected PDF Here</p>
          <p className="text-xs font-semibold text-slate-500">Strips restrictions & removes password lock</p>
          <input ref={inputRef} type="file" accept=".pdf,application/pdf" hidden onChange={(e) => e.target.files?.[0] && handleFile(e.target.files[0])} />
        </div>
      ) : (
        <div className="space-y-5 animate-fade-in">
          {/* File Bar */}
          <div className="flex items-center justify-between gap-3 p-3 bg-white border border-slate-300 rounded-lg shadow-xs">
            <div className="flex items-center gap-3 min-w-0">
              <FileText size={26} className="text-red-600 shrink-0" />
              <div className="min-w-0">
                <p className="font-extrabold text-sm text-slate-900 truncate">{file.name}</p>
                <p className="text-xs font-semibold text-slate-500">{formatSize(file.size)}</p>
              </div>
            </div>
            <button onClick={() => { setFile(null); setUnlocked(false); }} className="p-1.5 text-red-600 hover:bg-red-50 rounded border border-red-200 text-xs font-bold flex items-center gap-1 shrink-0 cursor-pointer">
              <X size={14} /> Remove
            </button>
          </div>

          {unlocked && (
            <div className="p-3 bg-green-50 border border-green-300 rounded-lg text-xs font-extrabold text-green-800 flex items-center gap-2">
              ✅ PDF successfully unlocked and downloaded!
            </div>
          )}

          {/* Password Input */}
          <div className="p-4 bg-slate-50 border border-slate-300 rounded-lg space-y-3">
            <div>
              <label className="text-xs font-extrabold text-slate-700 mb-1 block flex items-center gap-1">
                <KeyRound size={13} /> Current PDF Password (if required)
              </label>
              <div className="relative">
                <input
                  type={showPw ? "text" : "password"}
                  className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm font-bold focus:outline-none focus:border-slate-500 pr-10"
                  placeholder="Enter password (leave blank to strip restrictions only)..."
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  onKeyDown={(e) => e.key === "Enter" && handleUnlock()}
                />
                <button type="button" onClick={() => setShowPw(!showPw)}
                  className="absolute right-2 top-1/2 -translate-y-1/2 text-slate-400 hover:text-slate-600 cursor-pointer">
                  {showPw ? <EyeOff size={16} /> : <Eye size={16} />}
                </button>
              </div>
              <p className="text-[10px] font-semibold text-slate-500 mt-1">💡 Leave blank if you only want to strip print/copy restrictions from an already-open PDF.</p>
            </div>
          </div>

          {/* Two buttons */}
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
            <button onClick={handleUnlock} disabled={loading}
              style={{
                backgroundColor: "#059669",
                color: "#ffffff",
                borderTop: "2px solid #d1fae5",
                borderLeft: "2px solid #d1fae5",
                borderRight: "2px solid #064e3b",
                borderBottom: "2px solid #064e3b",
              }}
              className="py-3 text-sm font-extrabold flex items-center justify-center gap-2 cursor-pointer rounded shadow-md disabled:cursor-not-allowed disabled:opacity-60">
              {loading ? <><Loader2 size={18} className="animate-spin" /> Unlocking...</> : <><Unlock size={18} /> Unlock & Download PDF</>}
            </button>
            <button onClick={() => { setFile(null); setPassword(""); setUnlocked(false); }}
              className="py-3 text-sm font-bold flex items-center justify-center gap-2 cursor-pointer rounded border border-slate-300 bg-white hover:bg-slate-100 text-slate-700">
              <X size={16} /> Clear & Start Again
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import { notFound, useParams, useRouter } from "next/navigation";
import { PDF_TOOLS, PdfToolId } from "@/lib/pdf-tools-config";
import PageHeader from "@/components/layout/PageHeader";
import { ArrowLeft } from "lucide-react";
import Link from "next/link";

// Tool Components (to be implemented)
import MergePdfTool from "./components/MergePdfTool";
import SplitPdfTool from "./components/SplitPdfTool";
import CompressPdfTool from "./components/CompressPdfTool";
import PdfToJpgTool from "./components/PdfToJpgTool";
import JpgToPdfTool from "./components/JpgToPdfTool";
import ProtectPdfTool from "./components/ProtectPdfTool";
import UnlockPdfTool from "./components/UnlockPdfTool";
import RotatePdfTool from "./components/RotatePdfTool";
import DeletePagesTool from "./components/DeletePagesTool";
import ExtractPagesTool from "./components/ExtractPagesTool";
import ReorderPagesTool from "./components/ReorderPagesTool";
import AddSignatureTool from "./components/AddSignatureTool";
import RedactPdfTool from "./components/RedactPdfTool";
import EditPdfTool from "./components/EditPdfTool";

export default function ToolPage() {
  const params = useParams();
  const router = useRouter();
  const toolId = params.toolId as PdfToolId;

  const toolConfig = PDF_TOOLS.find((t) => t.id === toolId);

  if (!toolConfig) {
    notFound();
  }

  const renderTool = () => {
    switch (toolId) {
      case "merge": return <MergePdfTool />;
      case "split": return <SplitPdfTool />;
      case "compress": return <CompressPdfTool />;
      case "pdf-to-jpg": return <PdfToJpgTool />;
      case "jpg-to-pdf": return <JpgToPdfTool />;
      case "protect": return <ProtectPdfTool />;
      case "unlock": return <UnlockPdfTool />;
      case "rotate": return <RotatePdfTool />;
      case "delete-pages": return <DeletePagesTool />;
      case "extract-pages": return <ExtractPagesTool />;
      case "reorder-pages": return <ReorderPagesTool />;
      case "add-signature": return <AddSignatureTool />;
      case "redact": return <RedactPdfTool />;
      case "edit": return <EditPdfTool />;
      case "word-to-pdf":
        return (
          <div className="text-center py-20 animate-fade-in">
            <h3 className="text-2xl font-bold mb-4" style={{ color: "var(--text-primary)" }}>Word to PDF Component Coming Soon</h3>
            <p style={{ color: "var(--text-muted)" }}>This feature is currently under development.</p>
          </div>
        );
      default:
        return <div>Tool not found</div>;
    }
  };

  return (
    <div className="page-shell page-shell-tool relative pt-12">
      <Link href="/pdf-tools" className="absolute top-4 left-6 z-10 flex items-center gap-2 text-sm font-semibold hover:opacity-75 transition-opacity" style={{ color: "var(--text-primary)" }}>
        <ArrowLeft size={18} />
        Back to Tools
      </Link>

      <PageHeader
        title={toolConfig.title}
        subtitle={toolConfig.description}
      />

      <div className="mt-8">
        {renderTool()}
      </div>
    </div>
  );
}

"use client";

import { useState, useRef, useEffect, useCallback } from "react";
import { Camera, Download, RotateCw, Trash2, Sliders, Layout, Printer, Move, Plus, Minus, Eraser } from "lucide-react";
