              <span className="label text-red-500 font-extrabold">Kul Baaki Udhaar</span>
            </div>
            <span className="text-[10px] font-extrabold bg-red-600 text-white px-2 py-0.5 rounded-full">
              {data.pendingDueCustomers?.length || 0} Dues
