                                <td className="p-2 text-slate-700">{formatCurrency(detailedData.productSales.reduce((a, b) => a + b.revenue, 0))}</td>
                                <td className="p-2 text-green-700">{formatCurrency(detailedData.productSales.reduce((a, b) => a + b.profit, 0))}</td>
                              </tr>
                            </tfoot>
