"use client";

import { useState, useEffect } from "react";
import { Plus, Edit2, Trash2, ChevronDown, ChevronUp, Link as LinkIcon, Loader2 } from "lucide-react";
import { useToast } from "@/contexts/ToastContext";
import PageHeader from "@/components/layout/PageHeader";

export default function OnlineServicesAdminPage() {
  const [categories, setCategories] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [expandedCat, setExpandedCat] = useState<string | null>(null);
  const toast = useToast();

  const fetchCategories = async () => {
    try {
      const res = await fetch("/api/online-services");
      const data = await res.json();
      setCategories(data);
    } catch (err) {
      toast.error("Failed to load services");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchCategories();
  }, []);

  const handleDeleteCategory = async (id: string) => {
    if (!confirm("Delete this category?")) return;
    try {
      await fetch(`/api/online-services/${id}`, { method: "DELETE" });
      fetchCategories();
      toast.success("Deleted category");
    } catch {
      toast.error("Error deleting category");
    }
  };

  const handleDeleteLink = async (catId: string, linkId: string) => {
    if (!confirm("Delete this link?")) return;
    try {
      await fetch(`/api/online-services/${catId}/links/${linkId}`, { method: "DELETE" });
      fetchCategories();
      toast.success("Deleted link");
    } catch {
      toast.error("Error deleting link");
    }
  };

  if (loading) return <div className="flex justify-center p-8"><Loader2 className="animate-spin" /></div>;

  return (
    <div className="page-shell">
      <PageHeader title="Online Services Admin" subtitle="Manage categories and sub-links for Online Work page" />

      <div className="mb-4">
        <button className="btn btn-primary" onClick={() => {
          const title = prompt("Category Title?");
          if (title) {
             fetch("/api/online-services", {
               method: "POST",
               body: JSON.stringify({ title, order: categories.length + 1 }),
               headers: { "Content-Type": "application/json" }
             }).then(fetchCategories);
          }
        }}>
          <Plus size={16} /> Add Category
        </button>
      </div>

      <div className="space-y-4">
        {categories.map((cat) => (
          <div key={cat.id} className="glass-card overflow-hidden">
            <div className="flex justify-between items-center p-4 bg-black/20">
              <div className="flex items-center gap-3 cursor-pointer" onClick={() => setExpandedCat(expandedCat === cat.id ? null : cat.id)}>
                {expandedCat === cat.id ? <ChevronUp size={20} /> : <ChevronDown size={20} />}
                <span className="font-semibold">{cat.order}. {cat.title}</span>
              </div>
              <div className="flex gap-2">
                <button className="icon-btn text-blue-400" onClick={() => {
                  const title = prompt("New title?", cat.title);
                  if (title) {
                    fetch(`/api/online-services/${cat.id}`, {
                      method: "PUT",
                      body: JSON.stringify({ ...cat, title }),
                      headers: { "Content-Type": "application/json" }
                    }).then(fetchCategories);
                  }
                }}><Edit2 size={16} /></button>
                <button className="icon-btn text-red-400" onClick={() => handleDeleteCategory(cat.id)}><Trash2 size={16} /></button>
              </div>
            </div>

            {expandedCat === cat.id && (
              <div className="p-4 border-t border-white/10">
                <div className="mb-3">
                  <button className="btn btn-secondary text-sm" onClick={() => {
                    const title = prompt("Link Title?");
                    const href = prompt("URL?");
                    if (title && href) {
                       fetch(`/api/online-services/${cat.id}/links`, {
                         method: "POST",
                         body: JSON.stringify({ title, href, order: cat.links.length + 1 }),
                         headers: { "Content-Type": "application/json" }
                       }).then(fetchCategories);
                    }
                  }}>
                    <Plus size={14} /> Add Link
                  </button>
                </div>
                <div className="space-y-2">
                  {cat.links?.map((link: any) => (
                    <div key={link.id} className="flex justify-between items-center bg-black/10 p-2 rounded">
                      <div className="flex items-center gap-2 text-sm text-gray-300">
                        <LinkIcon size={14} />
                        {link.title} - <span className="text-gray-500">{link.href}</span>
                      </div>
                      <div className="flex gap-2">
                        <button className="icon-btn text-blue-400 p-1" onClick={() => {
                          const title = prompt("New title?", link.title) || link.title;
                          const href = prompt("New URL?", link.href) || link.href;
                          fetch(`/api/online-services/${cat.id}/links/${link.id}`, {
                            method: "PUT",
                            body: JSON.stringify({ ...link, title, href }),
                            headers: { "Content-Type": "application/json" }
                          }).then(fetchCategories);
                        }}><Edit2 size={14} /></button>
                        <button className="icon-btn text-red-400 p-1" onClick={() => handleDeleteLink(cat.id, link.id)}><Trash2 size={14} /></button>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            )}
          </div>
        ))}
      </div>
    </div>
  );
}

import { NextResponse } from "next/server";
import { GoogleGenAI } from "@google/genai";
import { prisma } from "@/lib/db";
import { auth } from "@/lib/auth";

const ai = new GoogleGenAI({ apiKey: process.env.GEMINI_API_KEY || "dummy" });

export async function POST(req: Request) {
  try {
    const session = await auth();
    if (!session) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const body = await req.json();
    const { messages } = body;

    if (!messages || !Array.isArray(messages)) {
      return NextResponse.json({ error: "Invalid messages array" }, { status: 400 });
    }

    if (!process.env.GEMINI_API_KEY) {
      return NextResponse.json(
        { error: "Gemini API key is missing. Please add GEMINI_API_KEY to your .env file." },
        { status: 500 }
      );
    }

    // Fetch contextual data for the AI
    const today = new Date();
    today.setHours(0, 0, 0, 0);

    const [pendingServicesCount, todayCustomersCount, totalCustomers] = await Promise.all([
      prisma.service.count({
        where: { status: { in: ["PENDING", "SUBMITTED", "PROCESSING"] } },
      }),
      prisma.customer.count({
        where: { createdAt: { gte: today } },
      }),
      prisma.customer.count(),
    ]);

    const systemPrompt = `You are a helpful AI assistant for "RA Seva Point", a digital service point shop. 
You answer questions about the shop, help with tasks, and provide business ideas.
Always reply in a helpful, concise, and friendly manner. If asked in Hindi/Hinglish, reply in Hinglish.

Here is the current real-time data from the shop's database:
- Total Customers: ${totalCustomers}
- Customers Added Today: ${todayCustomersCount}
- Pending/Active Online Services: ${pendingServicesCount}

You can use this data to answer questions like "kitne pending kaam hain" or "aaj kitne customers aaye".
If they ask for ideas, provide creative and practical business growth ideas for a digital service center (like CSC center, PAN card, Passport, Ticket Booking, etc.).
`;

    // Convert OpenAI style messages to Gemini style
    const geminiMessages = messages.map((msg: any) => ({
      role: msg.role === "user" ? "user" : "model",
      parts: [{ text: msg.content }],
    }));

    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash",
      contents: geminiMessages,
      config: {
        systemInstruction: systemPrompt,
        temperature: 0.7,
      },
    });

    return NextResponse.json({
      role: "assistant",
      content: response.text,
    });
  } catch (error: any) {
    console.error("AI Chat Error:", error);
    return NextResponse.json(
      { error: "Failed to generate AI response: " + error.message },
      { status: 500 }
    );
  }
}

import { prisma } from "@/lib/db";
import { auth } from "@/lib/auth";
import { NextRequest, NextResponse } from "next/server";

export async function GET(req: NextRequest, { params }: { params: Promise<{ id: string }> }) {
  const session = await auth();
  if (!session) return NextResponse.json({ error: "Unauthorized" }, { status: 401 });

  const { id } = await params;

  const customer = await prisma.customer.findUnique({
    where: { id },
    include: {
      services: { orderBy: { createdAt: "desc" } },
      invoices: { orderBy: { createdAt: "desc" }, include: { items: true } },
      documents: { orderBy: { createdAt: "desc" } },
    },
  });

  if (!customer) return NextResponse.json({ error: "Not found" }, { status: 404 });
  return NextResponse.json(customer);
}

export async function PUT(req: NextRequest, { params }: { params: Promise<{ id: string }> }) {
  const session = await auth();
  if (!session) return NextResponse.json({ error: "Unauthorized" }, { status: 401 });

  const { id } = await params;
  const body = await req.json();

  const customer = await prisma.customer.update({
    where: { id },
    data: {
      name: body.name,
      mobile: body.mobile,
      email: body.email || null,
      address: body.address || null,
      aadhaarNumber: body.aadhaarNumber || null,
      panNumber: body.panNumber || null,
      notes: body.notes || null,
    },
  });

  return NextResponse.json(customer);
}

export async function DELETE(req: NextRequest, { params }: { params: Promise<{ id: string }> }) {
  const session = await auth();
  if (!session) return NextResponse.json({ error: "Unauthorized" }, { status: 401 });

  const { id } = await params;

  try {
    await prisma.$transaction([
      prisma.service.deleteMany({ where: { customerId: id } }),
      prisma.document.deleteMany({ where: { customerId: id } }),
      prisma.invoice.deleteMany({ where: { customerId: id } }),
      prisma.customer.delete({ where: { id } }),
    ]);
    return NextResponse.json({ success: true });
  } catch (error: any) {
    console.error("Failed to delete customer:", error);
    return NextResponse.json({ error: "Failed to delete customer due to existing relations." }, { status: 500 });
  }
}

import { prisma } from "@/lib/db";
import { auth } from "@/lib/auth";
import { NextRequest, NextResponse } from "next/server";

export async function GET(req: NextRequest) {
  const session = await auth();
  if (!session) return NextResponse.json({ error: "Unauthorized" }, { status: 401 });

  const { searchParams } = new URL(req.url);
  const q = searchParams.get("q") || "";
  const page = parseInt(searchParams.get("page") || "1");
  const limit = parseInt(searchParams.get("limit") || "20");
  const skip = (page - 1) * limit;

  const where = q
    ? {
        OR: [
          { name: { contains: q, mode: "insensitive" as const } },
          { mobile: { contains: q } },
          { aadhaarNumber: { contains: q } },
          { panNumber: { contains: q, mode: "insensitive" as const } },
          { email: { contains: q, mode: "insensitive" as const } },
        ],
      }
    : {};

  const [customers, total] = await Promise.all([
    prisma.customer.findMany({
      where,
      skip,
      take: limit,
      orderBy: { createdAt: "desc" },
      include: {
        _count: { select: { services: true, invoices: true } },
      },
    }),
    prisma.customer.count({ where }),
  ]);

  return NextResponse.json({ customers, total, page, limit });
}

export async function POST(req: NextRequest) {
  const session = await auth();
  if (!session) return NextResponse.json({ error: "Unauthorized" }, { status: 401 });

  try {
    const body = await req.json();

    const customer = await prisma.customer.create({
      data: {
        name: body.name,
        mobile: body.mobile,
        email: body.email || null,
        address: body.address || null,
        aadhaarNumber: body.aadhaarNumber || null,
        panNumber: body.panNumber || null,
        notes: body.notes || null,
      },
    });

    await prisma.activityLog.create({
      data: {
        userId: (session.user as any).id,
        action: "CREATE_CUSTOMER",
        entity: "Customer",
        entityId: customer.id,
        details: `Created customer: ${customer.name}`,
      },
    });

    return NextResponse.json(customer, { status: 201 });
  } catch (error: any) {
    console.error("Failed to create customer:", error);
    if (error.code === "P2002") {
      return NextResponse.json(
        { error: "A customer with this mobile number already exists." },
        { status: 400 }
      );
    }
    return NextResponse.json(
      { error: "Internal Server Error" },
      { status: 500 }
    );
  }
}

