  const { id } = await params;
  const body = await req.json();

  if (!body.items || !Array.isArray(body.items) || body.items.length === 0) {
    return NextResponse.json({ error: "At least one item is required" }, { status: 400 });
  }

  const subtotal = body.items.reduce((sum: number, item: any) => sum + ((Number(item.quantity) || 1) * (Number(item.price) || 0)), 0);
  const discount = parseFloat(body.discount) || 0;
  const gst = parseFloat(body.gst) || 0;
  const total = subtotal - discount + ((subtotal * gst) / 100);
  let amountPaid = parseFloat(body.amountPaid) || 0;
  if (body.paymentStatus === "PAID") amountPaid = total;
  else if (body.paymentStatus === "UNPAID") amountPaid = 0;

  try {
    const updatedInvoice = await prisma.$transaction(async (tx) => {
      // Delete old items
      await tx.invoiceItem.deleteMany({ where: { invoiceId: id } });

      // Update invoice and re-create items
      return tx.invoice.update({
        where: { id },
        data: {
          customerId: body.customerId,
          subtotal,
          discount,
          gst,
          total,
          amountPaid,
          paymentMode: body.paymentMode,
          paymentStatus: body.paymentStatus,
          notes: body.notes || null,
          items: {
            create: body.items.map((item: any) => ({
              name: item.name,
              quantity: Number(item.quantity) || 1,
              price: Number(item.price) || 0,
              total: (Number(item.quantity) || 1) * (Number(item.price) || 0),
            })),
          },
        },
        include: {
          customer: { select: { id: true, name: true, mobile: true, address: true } },
          items: true,
          createdBy: { select: { name: true } },
        },
      });
    });

    const userId = (session.user as any).id;
    if (userId && userId !== "admin-hardcoded") {
      try {
        await prisma.activityLog.create({
          data: {
            userId,
            action: "UPDATE_INVOICE",
            entity: "Invoice",
            entityId: updatedInvoice.id,
            details: `Updated invoice #${updatedInvoice.invoiceNumber}`,
          },
        });
      } catch {}
    }

    return NextResponse.json(updatedInvoice);
  } catch (error: any) {
    console.error("Failed to update invoice:", error);
    return NextResponse.json({ error: error.message || "Failed to update invoice" }, { status: 500 });
  }
}

export async function DELETE(req: NextRequest, { params }: { params: Promise<{ id: string }> }) {
  const session = await auth();
  if (!session) return NextResponse.json({ error: "Unauthorized" }, { status: 401 });

  const { id } = await params;

  await prisma.invoice.delete({ where: { id } });
  return NextResponse.json({ success: true });
}

import { NextRequest, NextResponse } from "next/server";
import { PrismaClient } from "@prisma/client";

const prisma = new PrismaClient();

export async function POST(
  req: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const resolvedParams = await params;
    const body = await req.json();
    const { amountPaid, paymentMode } = body;

    if (amountPaid === undefined || amountPaid === null) {
      return NextResponse.json({ error: "amountPaid is required" }, { status: 400 });
    }

    const invoice = await prisma.invoice.findUnique({
      where: { id: resolvedParams.id },
    });

    if (!invoice) {
      return NextResponse.json({ error: "Invoice not found" }, { status: 404 });
    }

    const newAmountPaid = (invoice.amountPaid || 0) + Number(amountPaid);

    let paymentStatus = "PARTIAL";
    if (newAmountPaid >= invoice.total) {
      paymentStatus = "PAID";
    } else if (newAmountPaid <= 0) {
      paymentStatus = "UNPAID";
    }

    const updatedInvoice = await prisma.invoice.update({
      where: { id: resolvedParams.id },
      data: {
        amountPaid: newAmountPaid,
        paymentStatus: paymentStatus as any,
        paymentMode: paymentMode || invoice.paymentMode,
      },
    });

    return NextResponse.json(updatedInvoice);
  } catch (error: any) {
    console.error("Error settling invoice:", error);
    return NextResponse.json(
      { error: "Failed to settle invoice" },
      { status: 500 }
    );
  }
}

import { prisma } from "@/lib/db";
import { auth } from "@/lib/auth";
import { NextRequest, NextResponse } from "next/server";
import { generateInvoiceNumber } from "@/lib/utils";

export async function GET(req: NextRequest) {
  const session = await auth();
  if (!session) return NextResponse.json({ error: "Unauthorized" }, { status: 401 });

  const { searchParams } = new URL(req.url);
  const customerId = searchParams.get("customerId");
  const q = searchParams.get("q") || "";
  const paymentStatus = searchParams.get("paymentStatus") || "";
  const page = parseInt(searchParams.get("page") || "1");
  const limit = parseInt(searchParams.get("limit") || "20");
  const skip = (page - 1) * limit;

  const where: any = {};
  if (customerId) where.customerId = customerId;
  if (paymentStatus) where.paymentStatus = paymentStatus;
  if (q) {
    where.OR = [
      { invoiceNumber: { contains: q, mode: "insensitive" } },
      { customer: { name: { contains: q, mode: "insensitive" } } },
      { customer: { mobile: { contains: q } } },
    ];
  }

  const [invoices, total] = await Promise.all([
    prisma.invoice.findMany({
      where,
      skip,
      take: limit,
      orderBy: { createdAt: "desc" },
      include: {
        customer: { select: { id: true, name: true, mobile: true } },
        items: true,
      },
    }),
    prisma.invoice.count({ where }),
  ]);

  return NextResponse.json({ invoices, total, page, limit });
}


export async function POST(req: NextRequest) {
  const session = await auth();
  if (!session) return NextResponse.json({ error: "Unauthorized" }, { status: 401 });

  const body = await req.json();
  const invoiceNumber = generateInvoiceNumber();

  const subtotal = body.items.reduce(
    (sum: number, item: any) => sum + item.quantity * item.price,
    0
  );
  const discount = parseFloat(body.discount) || 0;
  const gst = parseFloat(body.gst) || 0;
  const total = subtotal - discount + (subtotal * gst) / 100;

  const invoice = await prisma.invoice.create({
    data: {
      invoiceNumber,
      customerId: body.customerId,
      createdById: (session.user as any).id,
      subtotal,
      discount,
      gst,
      total,
      amountPaid: Number(body.amountPaid) || 0,
      paymentMode: body.paymentMode || "CASH",
      paymentStatus: body.paymentStatus || "UNPAID",
      type: body.type || "INVOICE",
      dueDate: body.dueDate ? new Date(body.dueDate) : null,
      notes: body.notes || null,
      items: {
        create: body.items.map((item: any) => ({
          name: item.name,
          quantity: parseInt(item.quantity),
          price: parseFloat(item.price),
          total: parseInt(item.quantity) * parseFloat(item.price),
        })),
      },
    },
    include: {
      customer: { select: { id: true, name: true, mobile: true } },
      items: true,
    },
  });

  // Decrease inventory for each sold item
  if (body.items && body.items.length > 0) {
    for (const item of body.items) {
      const qty = parseInt(item.quantity);
      if (qty > 0) {
        // Find if this item name exists in inventory and is NOT a Service
        await prisma.inventoryItem.updateMany({
          where: { 
            name: item.name,
            category: { not: "Service" }
          },
          data: {
            quantity: {
              decrement: qty,
            },
          },
        });
      }
    }
  }

  return NextResponse.json(invoice, { status: 201 });
}

