import { prisma } from "@/lib/db";
import { auth } from "@/lib/auth";
import { NextRequest, NextResponse } from "next/server";
import { startOfDay, subDays } from "date-fns";

export async function GET(req: NextRequest) {
  const session = await auth();
  if (!session) return NextResponse.json({ error: "Unauthorized" }, { status: 401 });

  const { searchParams } = new URL(req.url);
  const range = searchParams.get("range") || "30";
  const days = parseInt(range, 10);

  const today = new Date();
  const startRange = startOfDay(subDays(today, days - 1));

  try {
    // 1. Get all PAID invoices within range
    const invoices = await prisma.invoice.findMany({
      where: {
        paymentStatus: { in: ["PAID", "PARTIAL"] },
        createdAt: { gte: startRange },
      },
      include: { items: true },
    });

    // 2. Aggregate InvoiceItems
    const productSalesMap = new Map<string, { quantity: number; revenue: number }>();
    for (const inv of invoices) {
      for (const item of inv.items) {
        const current = productSalesMap.get(item.name) || { quantity: 0, revenue: 0 };
        current.quantity += item.quantity;
        current.revenue += item.total;
        productSalesMap.set(item.name, current);
      }
    }

    // 3. Get all Inventory items to find purchase prices and categories
    const inventory = await prisma.inventoryItem.findMany({
      select: { name: true, purchasePrice: true, category: true },
    });
    const inventoryMap = new Map<string, { purchasePrice: number; isService: boolean }>();
    for (const inv of inventory) {
      inventoryMap.set(inv.name, {
        purchasePrice: inv.purchasePrice,
        isService: inv.category === "Service"
      });
    }

    // 4. Calculate product profit and separate POS services
    const productSales: any[] = [];
    const serviceSalesMap = new Map<string, { quantity: number; profit: number }>();

    for (const [name, data] of Array.from(productSalesMap.entries())) {
      const invData = inventoryMap.get(name);

      if (invData?.isService) {
        // This is a POS Service (100% profit usually, or just use revenue)
        serviceSalesMap.set(name, {
          quantity: data.quantity,
          profit: data.revenue,
        });
      } else {
        // This is a Product
        const purchasePrice = invData?.purchasePrice || 0;
        const totalPurchaseCost = purchasePrice * data.quantity;
        const profit = data.revenue - totalPurchaseCost;

        productSales.push({
          name,
          quantity: data.quantity,
          revenue: data.revenue,
          purchasePrice,
          totalPurchaseCost,
          profit,
        });
      }
    }

    // 5. Get all PAID services within range
    const services = await prisma.service.findMany({
      where: {
        paymentStatus: "PAID",
        createdAt: { gte: startRange },
      },
      select: { serviceType: true, fees: true },
    });

    // 6. Aggregate Service Profits into the existing serviceSalesMap
    for (const srv of services) {
      const current = serviceSalesMap.get(srv.serviceType) || { quantity: 0, profit: 0 };
      current.quantity += 1;
      current.profit += srv.fees;
      serviceSalesMap.set(srv.serviceType, current);
    }

    const serviceSales = Array.from(serviceSalesMap.entries()).map(([name, data]) => ({
      name,
      quantity: data.quantity,
      profit: data.profit,
    }));

    return NextResponse.json({
      productSales: productSales.sort((a, b) => b.profit - a.profit),
      serviceSales: serviceSales.sort((a, b) => b.profit - a.profit),
      dateRange: { start: startRange.toISOString(), end: today.toISOString() },
    });
  } catch (error) {
    console.error("Detailed report fetch error:", error);
    return NextResponse.json({ error: "Failed to fetch detailed report" }, { status: 500 });
  }
}

import { prisma } from "@/lib/db";
import { auth } from "@/lib/auth";
import { NextRequest, NextResponse } from "next/server";
import { startOfDay, endOfDay, startOfMonth, endOfMonth, subDays, format } from "date-fns";

export async function GET(req: NextRequest) {
  const session = await auth();
  if (!session) return NextResponse.json({ error: "Unauthorized" }, { status: 401 });

  const { searchParams } = new URL(req.url);
  const range = searchParams.get("range") || "7"; // "7" | "30" | "90"
  const days = parseInt(range);

  const today = new Date();
  const startRange = startOfDay(subDays(today, days - 1));
  const endRange = endOfDay(today);
  const startMonth = startOfMonth(today);
  const endMonth = endOfMonth(today);

  // Generate date labels for chart
  const dateLabels: string[] = [];
  for (let i = days - 1; i >= 0; i--) {
    dateLabels.push(format(subDays(today, i), "dd MMM"));
  }

  const [
    totalSalesAgg,
    totalServiceSalesAgg,
    monthSalesAgg,
    monthServiceSalesAgg,
    todaySalesAgg,
    todayServiceSalesAgg,
    invoicesInRange,
    servicesInRange,
    totalServices,
    totalCustomers,
    topServices,
    invoicesByPaymentStatus,
    recentLargeInvoices,
    invoicesWithItems,
    inventoryItems,
    serviceSalesTotalInRange,
  ] = await Promise.all([
    // Total all-time invoice revenue
    prisma.invoice.aggregate({
      where: { paymentStatus: { in: ["PAID", "PARTIAL"] } },
      _sum: { amountPaid: true },
      _count: true,
    }),
    // Total all-time service revenue
    prisma.service.aggregate({
      where: { paymentStatus: "PAID" },
      _sum: { fees: true },
    }),
    // This month invoice revenue
    prisma.invoice.aggregate({
      where: {
        paymentStatus: { in: ["PAID", "PARTIAL"] },
        createdAt: { gte: startMonth, lte: endMonth },
      },
      _sum: { amountPaid: true },
      _count: true,
    }),
    // This month service revenue
    prisma.service.aggregate({
      where: {
        paymentStatus: "PAID",
        createdAt: { gte: startMonth, lte: endMonth },
      },
      _sum: { fees: true },
    }),
    // Today invoice revenue
    prisma.invoice.aggregate({
      where: {
        paymentStatus: { in: ["PAID", "PARTIAL"] },
        createdAt: { gte: startOfDay(today), lte: endOfDay(today) },
      },
      _sum: { amountPaid: true },
      _count: true,
    }),
    // Today service revenue
    prisma.service.aggregate({
      where: {
        paymentStatus: "PAID",
        createdAt: { gte: startOfDay(today), lte: endOfDay(today) },
      },
      _sum: { fees: true },
    }),
    // Invoices for chart range
    prisma.invoice.findMany({
      where: {
        paymentStatus: { in: ["PAID", "PARTIAL"] },
        createdAt: { gte: startRange, lte: endRange },
      },
      select: { amountPaid: true, createdAt: true },
      orderBy: { createdAt: "asc" },
    }),
    // Services for chart range
    prisma.service.findMany({
      where: {
        paymentStatus: "PAID",
        createdAt: { gte: startRange, lte: endRange },
      },
      select: { fees: true, createdAt: true },
      orderBy: { createdAt: "asc" },
    }),
    // Total services counts
    prisma.service.groupBy({
      by: ["status"],
      _count: true,
    }),
    // Total customers
    prisma.customer.count(),
    // Top service types by count
    prisma.service.groupBy({
      by: ["serviceType"],
      _count: { serviceType: true },
      orderBy: { _count: { serviceType: "desc" } },
      take: 5,
    }),
    // Invoices by payment status
    prisma.invoice.groupBy({
      by: ["paymentStatus"],
      _sum: { total: true },
      _count: true,
    }),
    // Recent large invoices
    prisma.invoice.findMany({
      take: 5,
      orderBy: { total: "desc" },
      where: {
        createdAt: { gte: startRange, lte: endRange },
      },
      include: {
        customer: { select: { name: true, mobile: true } },
      },
    }),
    // Invoices with items for accurate Product vs POS Service separation
    prisma.invoice.findMany({
      where: { paymentStatus: { in: ["PAID", "PARTIAL"] }, createdAt: { gte: startRange, lte: endRange } },
      include: { items: true },
    }),
    prisma.inventoryItem.findMany({
      select: { name: true, category: true }
    }),
    // Service sales total in range
    prisma.service.aggregate({
      where: { paymentStatus: "PAID", createdAt: { gte: startRange, lte: endRange } },
      _sum: { fees: true },
      _count: true,
    }),
  ]);

  // Separate Product vs Service revenue for POS Invoices
  const inventoryMap = new Map(inventoryItems.map(i => [i.name, i.category]));
  let posProductRevenue = 0;
  let posServiceRevenue = 0;
  let posProductCount = 0;

  for (const inv of invoicesWithItems) {
    let invProductTotal = 0;
    let invServiceTotal = 0;

    for (const item of inv.items) {
      const category = inventoryMap.get(item.name);
      if (category === "Service") {
        invServiceTotal += item.total;
      } else {
        invProductTotal += item.total;
        posProductCount += item.quantity; // approximate product sales count
      }
    }

    if (inv.paymentStatus === "PAID") {
      posProductRevenue += invProductTotal;
      posServiceRevenue += invServiceTotal;
    } else if (inv.paymentStatus === "PARTIAL") {
      // distribute amountPaid proportionally
      const ratio = inv.total > 0 ? (inv.amountPaid / inv.total) : 0;
      posProductRevenue += (invProductTotal * ratio);
      posServiceRevenue += (invServiceTotal * ratio);
    }
  }

  // Build daily chart data
  const revenueByDate: Record<string, number> = {};
  for (let i = days - 1; i >= 0; i--) {
    const label = format(subDays(today, i), "dd MMM");
    revenueByDate[label] = 0;
  }
  for (const inv of invoicesInRange) {
    const label = format(new Date(inv.createdAt), "dd MMM");
    if (label in revenueByDate) {
      revenueByDate[label] += inv.amountPaid || 0;
    }
  }
  for (const srv of servicesInRange) {
    const label = format(new Date(srv.createdAt), "dd MMM");
    if (label in revenueByDate) {
      revenueByDate[label] += srv.fees;
    }
  }
  const chartData = Object.entries(revenueByDate).map(([date, revenue]) => ({
    date,
    revenue: Math.round(revenue),
  }));

  // Calculate pending dues per customer
  const [unpaidInvoices, unpaidServices] = await Promise.all([
    prisma.invoice.findMany({
      where: { paymentStatus: { in: ["UNPAID", "PARTIAL"] } },
      include: { customer: true },
    }),
    prisma.service.findMany({
      where: { paymentStatus: { in: ["UNPAID", "PARTIAL"] } },
      include: { customer: true },
    }),
  ]);

  const customerDuesMap: Record<string, { customer: any; totalDue: number; totalBilled: number; invoiceCount: number; serviceCount: number }> = {};

  for (const inv of unpaidInvoices) {
    if (!inv.customer) continue;
    const cid = inv.customerId;
    const due = inv.total - inv.amountPaid;
    if (due <= 0) continue;

    if (!customerDuesMap[cid]) {
      customerDuesMap[cid] = {
        customer: inv.customer,
        totalDue: 0,
        totalBilled: 0,
        invoiceCount: 0,
        serviceCount: 0,
      };
    }
    customerDuesMap[cid].totalDue += due;
    customerDuesMap[cid].totalBilled += inv.total;
    customerDuesMap[cid].invoiceCount += 1;
  }

  for (const srv of unpaidServices) {
    if (!srv.customer) continue;
    const cid = srv.customerId;
    const due = srv.fees;
    if (due <= 0) continue;

    if (!customerDuesMap[cid]) {
      customerDuesMap[cid] = {
        customer: srv.customer,
        totalDue: 0,
        totalBilled: 0,
        invoiceCount: 0,
        serviceCount: 0,
      };
    }
    customerDuesMap[cid].totalDue += due;
    customerDuesMap[cid].totalBilled += srv.fees;
    customerDuesMap[cid].serviceCount += 1;
  }

  const pendingDueCustomers = Object.values(customerDuesMap).sort((a, b) => b.totalDue - a.totalDue);
  const totalPendingDueBalance = pendingDueCustomers.reduce((acc, c) => acc + c.totalDue, 0);

  // Service status breakdown
  const serviceStats: Record<string, number> = {};
  for (const s of totalServices) {
    serviceStats[s.status] = s._count;
  }

  return NextResponse.json({
    summary: {
      allTimeRevenue: (totalSalesAgg._sum.amountPaid || 0) + (totalServiceSalesAgg._sum.fees || 0),
      allTimeInvoices: totalSalesAgg._count,
      monthRevenue: (monthSalesAgg._sum.amountPaid || 0) + (monthServiceSalesAgg._sum.fees || 0),
      monthInvoices: monthSalesAgg._count,
      todayRevenue: (todaySalesAgg._sum.amountPaid || 0) + (todayServiceSalesAgg._sum.fees || 0),
      todayInvoices: todaySalesAgg._count,
      totalCustomers,
      inventorySalesRevenue: Math.round(posProductRevenue),
      inventorySalesCount: posProductCount,
      serviceSalesRevenue: Math.round((serviceSalesTotalInRange._sum.fees || 0) + posServiceRevenue),
      serviceSalesCount: serviceSalesTotalInRange._count,
      totalPendingDueBalance,
    },
    chartData,
    serviceStats,
    topServices: topServices.map((s) => ({
      name: s.serviceType,
      count: s._count.serviceType,
    })),
    invoicesByPaymentStatus: invoicesByPaymentStatus.map((s) => ({
      status: s.paymentStatus,
      total: s._sum.total || 0,
      count: s._count,
    })),
    recentLargeInvoices,
    pendingDueCustomers,
  });
}

import { auth } from "@/lib/auth";
import { prisma } from "@/lib/db";
import type { GlobalSearchResult } from "@/lib/search";
import { NextRequest, NextResponse } from "next/server";

export async function GET(req: NextRequest) {
  const session = await auth();
  if (!session) return NextResponse.json({ error: "Unauthorized" }, { status: 401 });

  const { searchParams } = new URL(req.url);
  const query = (searchParams.get("q") || "").trim();
  const requestedLimit = Number.parseInt(searchParams.get("limit") || "10", 10);
  const limit = Number.isFinite(requestedLimit)
    ? Math.min(Math.max(requestedLimit, 5), 20)
    : 10;

  if (query.length < 2) {
    return NextResponse.json({ results: [] satisfies GlobalSearchResult[] });
  }


  const perGroup = Math.max(3, Math.ceil(limit / 3));
  const customerWhere = {
    OR: [
      { name: { contains: query} },
      { mobile: { contains: query } },
      { aadhaarNumber: { contains: query } },
      { panNumber: { contains: query} },
      { email: { contains: query} },
    ],
  };

  let customers: any[] = [], invoices: any[] = [], services: any[] = [], books: any[] = [], inventoryItems: any[] = [];
  try {
    [customers, invoices, services, books, inventoryItems] = await Promise.all([
      prisma.customer.findMany({
        where: customerWhere,
        take: perGroup,
        orderBy: { updatedAt: "desc" },
        select: {
          id: true,
          name: true,
          mobile: true,
          aadhaarNumber: true,
          panNumber: true,
        },
      }),
      prisma.invoice.findMany({
        where: {
          OR: [
            { invoiceNumber: { contains: query} },
            { notes: { contains: query} },
            { customer: { is: customerWhere } },
            { items: { some: { name: { contains: query} } } },
          ],
        },
        take: perGroup,
        orderBy: { updatedAt: "desc" },
        select: {
          id: true,
          invoiceNumber: true,
          total: true,
          paymentStatus: true,
          customer: { select: { name: true, mobile: true } },
        },
      }),
      prisma.service.findMany({
        where: {
          OR: [
            { serviceType: { contains: query} },
            { notes: { contains: query} },
            { customer: { is: customerWhere } },
          ],
        },
        take: perGroup,
        orderBy: { updatedAt: "desc" },
        select: {
          id: true,
          serviceType: true,
          status: true,
          fees: true,
          customer: { select: { name: true, mobile: true } },
        },
      }),
      prisma.book.findMany({
        where: {
          OR: [
            { name: { contains: query} },
            { author: { contains: query} },
            { category: { contains: query} },
            { isbn: { contains: query} },
            { barcode: { contains: query } },
          ],
        },
        take: perGroup,
        orderBy: { updatedAt: "desc" },
        select: {
          id: true,
          name: true,
          author: true,
          isbn: true,
          barcode: true,
          quantity: true,
        },
      }),
      prisma.inventoryItem.findMany({
        where: {
          OR: [
            { name: { contains: query} },
            { category: { contains: query} },
          ],
        },
        take: perGroup,
        orderBy: { updatedAt: "desc" },
        select: {
          id: true,
          name: true,
          category: true,
          quantity: true,
          unit: true,
        },
      }),
    ]);
  } catch (err) {
    console.error("Search API Error:", err);
    // Continue with empty arrays if search fails
  }

  const results: GlobalSearchResult[] = [
    ...customers.map((customer) => ({
      id: customer.id,
      type: "customer" as const,
      title: customer.name,
      subtitle: [customer.mobile, customer.panNumber, customer.aadhaarNumber]
        .filter(Boolean)
        .join(" | "),
      href: `/customers/${customer.id}`,
      badge: "Customer",
    })),
    ...invoices.map((invoice) => ({
      id: invoice.id,
      type: "invoice" as const,
      title: invoice.invoiceNumber,
      subtitle: `${invoice.customer.name} | ${invoice.customer.mobile} | Rs ${invoice.total.toLocaleString("en-IN")}`,
      href: `/billing/${invoice.id}`,
      badge: invoice.paymentStatus,
    })),
    ...services.map((service) => ({
      id: service.id,
      type: "service" as const,
      title: service.serviceType,
      subtitle: `${service.customer.name} | ${service.customer.mobile} | Ref ${service.id.slice(-6).toUpperCase()}`,
      href: `/services/${service.id}`,
      badge: service.status,
    })),
    ...books.map((book) => ({
      id: book.id,
      type: "book" as const,
      title: book.name,
      subtitle: [book.author, book.isbn, book.barcode, `Stock ${book.quantity}`]
        .filter(Boolean)
        .join(" | "),
      href: "/books",
      badge: "Book",
    })),
    ...inventoryItems.map((item) => ({
      id: item.id,
      type: "inventory" as const,
      title: item.name,
      subtitle: `${item.category} | Stock ${item.quantity} ${item.unit}`,
      href: `/inventory?edit=${item.id}`,
      badge: "Product",
    })),
  ].slice(0, limit);

  return NextResponse.json({ results });
}

