export async function PUT(req: NextRequest, { params }: { params: Promise<{ id: string }> }) {
  const session = await auth();
  if (!session) return NextResponse.json({ error: "Unauthorized" }, { status: 401 });

  const { id } = await params;
  const body = await req.json();

  const service = await prisma.service.update({
    where: { id },
    data: {
      status: body.status,
      fees: parseFloat(body.fees) || 0,
      paymentStatus: body.paymentStatus,
      paymentMode: body.paymentMode,
      notes: body.notes || null,
      requiredDocs: body.requiredDocs !== undefined ? body.requiredDocs : undefined,
      submittedAt: body.status === "SUBMITTED" ? new Date() : undefined,
      approvedAt: body.status === "APPROVED" ? new Date() : undefined,
      deliveredAt: body.status === "DELIVERED" ? new Date() : undefined,
      deadline: body.deadline !== undefined ? (body.deadline ? new Date(body.deadline) : null) : undefined,
      referenceNo: body.referenceNo !== undefined ? body.referenceNo : undefined,
      vendorId: body.vendorId !== undefined ? body.vendorId : undefined,
      vendorCost: body.vendorCost !== undefined ? parseFloat(body.vendorCost) : undefined,
      missingDocs: body.missingDocs !== undefined ? body.missingDocs : undefined,
      tasks: body.tasks !== undefined ? body.tasks : undefined,
    },
  });

  const userId = (session.user as any).id;
  if (userId !== "admin-hardcoded") {
    await prisma.activityLog.create({
      data: {
        userId: userId,
        action: "UPDATE_SERVICE_STATUS",
        entity: "Service",
        entityId: service.id,
        details: `Updated service status to ${service.status}`,
      },
    });
  }

  return NextResponse.json(service);
}

export async function DELETE(req: NextRequest, { params }: { params: Promise<{ id: string }> }) {
  const session = await auth();
  if (!session) return NextResponse.json({ error: "Unauthorized" }, { status: 401 });

  const { id } = await params;

  await prisma.service.delete({ where: { id } });
  return NextResponse.json({ success: true });
}

import { NextResponse } from "next/server";
import { prisma } from "@/lib/db";

export async function PUT(req: Request) {
  try {
    const { ids, status } = await req.json();

    if (!ids || !Array.isArray(ids) || ids.length === 0) {
      return NextResponse.json(
        { error: "No service IDs provided" },
        { status: 400 }
      );
    }

    if (!status) {
      return NextResponse.json(
        { error: "No status provided" },
        { status: 400 }
      );
    }

    // Prepare update data based on status
    const updateData: any = { status };
    if (status === "DELIVERED") {
      updateData.deliveredAt = new Date();
    } else if (status === "APPROVED") {
      updateData.approvedAt = new Date();
    } else if (status === "SUBMITTED") {
      updateData.submittedAt = new Date();
    }

    const updatedServices = await prisma.service.updateMany({
      where: {
        id: {
          in: ids,
        },
      },
      data: updateData,
    });

    return NextResponse.json({
      success: true,
      count: updatedServices.count,
    });
  } catch (error: any) {
    console.error("Error bulk updating services:", error);
    return NextResponse.json(
      { error: "Failed to update services" },
      { status: 500 }
    );
  }
}

import { prisma } from "@/lib/db";
import { auth } from "@/lib/auth";
import { NextRequest, NextResponse } from "next/server";

export async function GET(req: NextRequest) {
  const session = await auth();
  if (!session) return NextResponse.json({ error: "Unauthorized" }, { status: 401 });

  const { searchParams } = new URL(req.url);
  const status = searchParams.get("status");
  const type = searchParams.get("type");
  const customerId = searchParams.get("customerId");
  const page = parseInt(searchParams.get("page") || "1");
  const limit = parseInt(searchParams.get("limit") || "20");
  const skip = (page - 1) * limit;

  const where: any = {};
  if (status) where.status = status;
  if (type) where.serviceType = { contains: type, mode: "insensitive" };
  if (customerId) where.customerId = customerId;

  const [services, total] = await Promise.all([
    prisma.service.findMany({
      where,
      skip,
      take: limit,
      orderBy: { createdAt: "desc" },
      include: {
        customer: { select: { id: true, name: true, mobile: true } },
        assignedTo: { select: { id: true, name: true } },
      },
    }),
    prisma.service.count({ where }),
  ]);

  return NextResponse.json({ services, total, page, limit });
}

export async function POST(req: NextRequest) {
  const session = await auth();
  if (!session) return NextResponse.json({ error: "Unauthorized" }, { status: 401 });

  const body = await req.json();

  const service = await prisma.service.create({
    data: {
      customerId: body.customerId,
      serviceType: body.serviceType,
      status: "PENDING",
      fees: parseFloat(body.fees) || 0,
      paymentStatus: body.paymentStatus || "UNPAID",
      paymentMode: body.paymentMode || "PENDING",
      notes: body.notes || null,
      requiredDocs: body.requiredDocs || [],
      assignedToId: (session.user as any).id,
      trackingId: body.trackingId || null,
      deadline: body.deadline ? new Date(body.deadline) : null,
      referenceNo: body.referenceNo || null,
      vendorId: body.vendorId || null,
      vendorCost: parseFloat(body.vendorCost) || 0,
      missingDocs: body.missingDocs || null,
    },
    include: {
      customer: { select: { id: true, name: true, mobile: true } },
    },
  });

  await prisma.activityLog.create({
    data: {
      userId: (session.user as any).id,
      action: "CREATE_SERVICE",
      entity: "Service",
      entityId: service.id,
      details: `Created service: ${service.serviceType} for ${service.customer.name}`,
    },
  });

  return NextResponse.json(service, { status: 201 });
}

import { prisma } from "@/lib/db";
import { auth } from "@/lib/auth";
import { NextRequest, NextResponse } from "next/server";

// Default settings
const DEFAULTS: Record<string, string> = {
  shopName: "RA Seva Point",
  tagline: "One Stop for Books, Print & Digital Services",
  upiId: "rasevapoint@upi",
  gstEnabled: "false",
  shopAddress: "",
  shopPhone: "",
  shopEmail: "",
};

export async function GET() {
  const session = await auth();
  if (!session) return NextResponse.json({ error: "Unauthorized" }, { status: 401 });

  try {
    const rows = await prisma.shopSettings.findMany();
    const settings: Record<string, string> = { ...DEFAULTS };
    for (const row of rows) {
      settings[row.key] = row.value;
    }
    return NextResponse.json(settings);
  } catch {
    return NextResponse.json(DEFAULTS);
  }
}

export async function POST(req: NextRequest) {
  const session = await auth();
  if (!session) return NextResponse.json({ error: "Unauthorized" }, { status: 401 });

  const body = await req.json();

  // Upsert each key-value pair
  const updates = Object.entries(body).filter(([key]) => key in DEFAULTS);

  await Promise.all(
    updates.map(([key, value]) =>
      prisma.shopSettings.upsert({
        where: { key },
        update: { value: String(value) },
        create: { key, value: String(value) },
      })
    )
  );

  // Log the action
  await prisma.activityLog.create({
    data: {
      userId: (session.user as any).id,
      action: "UPDATE_SETTINGS",
      entity: "ShopSettings",
      details: `Updated shop settings`,
    },
  });

  return NextResponse.json({ success: true });
}

import { prisma } from "@/lib/db";
import { auth } from "@/lib/auth";
import { NextRequest, NextResponse } from "next/server";

export async function GET(
  req: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  const resolvedParams = await params;
  const session = await auth();
  if (!session) return NextResponse.json({ error: "Unauthorized" }, { status: 401 });

  const transactions = await prisma.vendorTransaction.findMany({
    where: { vendorId: resolvedParams.id },
    orderBy: { date: "desc" },
  });

  return NextResponse.json({ transactions });
}

export async function POST(
  req: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  const resolvedParams = await params;
  const session = await auth();
  if (!session) return NextResponse.json({ error: "Unauthorized" }, { status: 401 });

  const body = await req.json();
  const { type, amount, description, date } = body;

  if (!type || !amount) {
    return NextResponse.json({ error: "Type and amount are required" }, { status: 400 });
  }

  const parsedAmount = parseFloat(amount);

  try {
    const transaction = await prisma.$transaction(async (tx) => {
      // 1. Create transaction
      const t = await tx.vendorTransaction.create({
        data: {
          vendorId: resolvedParams.id,
          type, // "PURCHASE" or "PAYMENT"
          amount: parsedAmount,
          description,
          date: date ? new Date(date) : new Date(),
        },
      });

      // 2. Update vendor balance
      // If we made a PURCHASE (Udhaar), the balance we owe INCREASES
      // If we made a PAYMENT to them, the balance we owe DECREASES
      const balanceChange = type === "PURCHASE" ? parsedAmount : -parsedAmount;

      await tx.vendor.update({
        where: { id: resolvedParams.id },
        data: {
          balance: { increment: balanceChange },
        },
      });

      return t;
    });

    return NextResponse.json(transaction);
  } catch (error) {
    return NextResponse.json({ error: "Failed to process transaction" }, { status: 500 });
  }
}

