        <div className="text-right">
          <p><strong>Date:</strong> {formatDate(new Date().toISOString())}</p>
          <p><strong>Total Due Balance:</strong> <span className="text-red-600 font-bold text-xl">{formatCurrency(totalDue)}</span></p>
