import React, { useState, useEffect, useRef } from "react";
import { useRouter } from "next/navigation";
import { useToast } from "@/contexts/ToastContext";
import { formatCurrency } from "@/lib/utils";
import LegacyDialog from "@/components/layout/LegacyDialog";

import AddCustomerDialog from "@/components/customers/AddCustomerDialog";

interface InvoiceItemInput {
  name: string;
  quantity: number;
  price: number;
}

interface InventorySuggestion {
  id: string;
  name: string;
  sellingPrice: number;
  quantity: number;
  unit: string;
  category: string;
}

// ── Inventory Autocomplete Dropdown (Legacy Style) ──────────────────────────
function ItemNameInput({
  index,
  value,
  onChange,
  onSelectInventory,
}: {
  index: number;
  value: string;
  onChange: (val: string) => void;
  onSelectInventory: (item: InventorySuggestion) => void;
}) {
  const [suggestions, setSuggestions] = useState<InventorySuggestion[]>([]);
  const [open, setOpen] = useState(false);
  const [activeIdx, setActiveIdx] = useState(-1);
  const wrapRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!value.trim() || value.length < 1) {
      setSuggestions([]);
      setOpen(false);
      return;
    }
    const t = setTimeout(async () => {
      try {
        const res = await fetch(`/api/inventory?q=${encodeURIComponent(value)}`);
        const data: InventorySuggestion[] = await res.json();
        setSuggestions(data.slice(0, 8));
        setOpen(data.length > 0);
        setActiveIdx(-1);
      } catch {
        setSuggestions([]);
        setOpen(false);
      }
    }, 200);
    return () => clearTimeout(t);
  }, [value]);

  useEffect(() => {
    const handler = (e: MouseEvent) => {
      if (wrapRef.current && !wrapRef.current.contains(e.target as Node)) {
        setOpen(false);
      }
    };
    document.addEventListener("mousedown", handler);
    return () => document.removeEventListener("mousedown", handler);
  }, []);

  const handleSelect = (item: InventorySuggestion) => {
    onSelectInventory(item);
    setSuggestions([]);
    setOpen(false);
    setActiveIdx(-1);
  };

  const handleKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (!open || suggestions.length === 0) return;
    if (e.key === "ArrowDown") {
      e.preventDefault();
      setActiveIdx((i) => Math.min(i + 1, suggestions.length - 1));
    } else if (e.key === "ArrowUp") {
      e.preventDefault();
      setActiveIdx((i) => Math.max(i - 1, 0));
    } else if (e.key === "Enter" && activeIdx >= 0) {
      e.preventDefault();
      handleSelect(suggestions[activeIdx]);
    } else if (e.key === "Escape") {
      setOpen(false);
    }
  };

  return (
    <div ref={wrapRef} style={{ position: 'relative', flex: 1 }}>
      <input
        type="text"
        className="legacy-input"
        style={{ width: '100%' }}
        value={value}
        onChange={(e) => onChange(e.target.value)}
        onFocus={() => suggestions.length > 0 && setOpen(true)}
        onKeyDown={handleKeyDown}
        autoComplete="off"
        required
      />

      {open && suggestions.length > 0 && (
        <div style={{
            position: 'absolute', zIndex: 50, width: '100%', marginTop: '2px',
            background: '#fff', border: '1px solid black', boxShadow: '2px 2px 4px rgba(0,0,0,0.5)',
            maxHeight: '150px', overflowY: 'auto'
          }}
        >
          {suggestions.map((item, i) => (
            <div
              key={item.id}
              style={{
                padding: '2px 4px',
                background: activeIdx === i ? '#0a246a' : 'transparent',
                color: activeIdx === i ? '#fff' : '#000',
                cursor: 'pointer',
                display: 'flex', justifyContent: 'space-between'
              }}
              onMouseEnter={() => setActiveIdx(i)}
              onMouseDown={(e) => {
                e.preventDefault();
                handleSelect(item);
              }}
            >
              <span>{item.name}</span>
              <span style={{ fontSize: '9px' }}>₹{item.sellingPrice} ({item.quantity} left)</span>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

// ── Main Dialog ────────────────────────────────────────────────────────────────

interface NewBillDialogProps {
  isOpen: boolean;
  onClose: () => void;
  onSuccess?: () => void;
}

export default function NewBillDialog({ isOpen, onClose, onSuccess }: NewBillDialogProps) {
  const router = useRouter();
  const toast = useToast();
  const [loading, setLoading] = useState(false);
  const [customerSearch, setCustomerSearch] = useState("");
  const [customers, setCustomers] = useState<any[]>([]);
  const [selectedCustomer, setSelectedCustomer] = useState<any>(null);
  const [isAddCustomerOpen, setIsAddCustomerOpen] = useState(false);

  const [items, setItems] = useState<InvoiceItemInput[]>([{ name: "", quantity: 1, price: 0 }]);
  const [discount, setDiscount] = useState(0);
  const [gst, setGst] = useState(0);
  const [paymentMode, setPaymentMode] = useState("CASH");
  const [paymentStatus, setPaymentStatus] = useState("PAID");
  const [amountPaid, setAmountPaid] = useState<number | "">("");
  const [type, setType] = useState("INVOICE");
  const [dueDate, setDueDate] = useState("");
  const [notes, setNotes] = useState("");

  // Customer search
  useEffect(() => {
    if (!customerSearch.trim()) {
      setCustomers([]);
      return;
    }
    const t = setTimeout(async () => {
      const res = await fetch(`/api/customers?q=${encodeURIComponent(customerSearch)}&limit=5`);
      const data = await res.json();
      setCustomers(data.customers || []);
    }, 300);
    return () => clearTimeout(t);
  }, [customerSearch]);

  const subtotal = items.reduce((sum, item) => sum + item.quantity * item.price, 0);
  const total = subtotal - discount + (subtotal * gst) / 100;

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedCustomer) return toast.error("Please select a customer");
    if (items.some((item) => !item.name.trim() || item.quantity <= 0 || item.price < 0)) {
      return toast.error("Please fill in all item fields correctly");
    }

    setLoading(true);
    let finalAmountPaid = paymentStatus === "PAID" ? total : paymentStatus === "PARTIAL" ? (Number(amountPaid) || 0) : 0;

    try {
      const res = await fetch("/api/invoices", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          customerId: selectedCustomer.id,
          items, discount, gst, paymentMode, paymentStatus,
          amountPaid: finalAmountPaid, notes,
          type, dueDate: dueDate ? new Date(dueDate).toISOString() : null,
        }),
      });
      if (!res.ok) throw new Error("Failed to create invoice");
      const invoice = await res.json();
      toast.success("Invoice created successfully!");
      if (onSuccess) onSuccess();
      onClose();
    } catch (err: any) {
      toast.error(err.message);
    } finally {
      setLoading(false);
    }
  };

  return (
    <>
      <LegacyDialog isOpen={isOpen} onClose={onClose} title="New Invoice / Bill" width="600px">
        <form onSubmit={handleSubmit} style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>

          {/* Customer Fieldset */}
          <div className="legacy-fieldset" style={{ marginTop: '12px' }}>
            <div className="legacy-legend">Customer Selection</div>

            {selectedCustomer ? (
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                <div>
                  <strong>{selectedCustomer.name}</strong> - {selectedCustomer.mobile}
                </div>
                <button type="button" className="legacy-button" onClick={() => setSelectedCustomer(null)}>Change</button>
              </div>
            ) : (
              <div style={{ position: 'relative' }}>
                <div style={{ display: 'flex', alignItems: 'center', gap: '6px' }}>
                  <label style={{ width: '50px' }}>Search:</label>
                  <input
                    type="text"
                    className="legacy-input"
                    style={{ flex: 1 }}
                    placeholder="Name or Mobile..."
                    value={customerSearch}
                    onChange={(e) => setCustomerSearch(e.target.value)}
                    autoComplete="off"
                  />
                  <button
                    type="button"
                    className="legacy-button"
                    onClick={() => setIsAddCustomerOpen(true)}
                    style={{ display: 'flex', alignItems: 'center', gap: '3px', fontWeight: 'bold', whiteSpace: 'nowrap', padding: '2px 8px' }}
                    title="Add New Customer"
                  >
                    <span style={{ color: 'green', fontWeight: 'bold', fontSize: '12px' }}>+</span> Add New Customer
                  </button>
                </div>
                {(customers.length > 0 || customerSearch.trim().length > 0) && (
                  <div style={{ position: 'absolute', zIndex: 10, width: 'calc(100% - 56px)', left: '56px', top: '100%', background: '#fff', border: '1px solid black', maxHeight: '140px', overflowY: 'auto', boxShadow: '2px 2px 5px rgba(0,0,0,0.2)' }}>
                    {customers.map((c) => (
                      <div
                        key={c.id}
                        style={{ padding: '4px 6px', cursor: 'pointer', borderBottom: '1px solid #dfdfdf' }}
                        onClick={() => { setSelectedCustomer(c); setCustomerSearch(""); setCustomers([]); }}
                      >
                        <strong>{c.name}</strong> ({c.mobile})
                      </div>
                    ))}
                    <div
                      style={{ padding: '4px 6px', cursor: 'pointer', background: '#f0f4ff', color: '#0a246a', fontWeight: 'bold', borderTop: customers.length > 0 ? '1px solid #0a246a' : 'none' }}
                      onClick={() => { setIsAddCustomerOpen(true); }}
                    >
                      + Create "{customerSearch}" as New Customer
                    </div>
                  </div>
                )}
              </div>
            )}
          </div>

        {/* Invoice Items Fieldset */}
        <div className="legacy-fieldset">
          <div className="legacy-legend">Invoice Items</div>
          <table className="legacy-grid">
            <thead>
              <tr>
                <th style={{ width: '50%' }}>Description</th>
                <th style={{ width: '15%' }}>Qty</th>
                <th style={{ width: '20%' }}>Price</th>
                <th style={{ width: '10%' }}>Total</th>
                <th style={{ width: '5%' }}></th>
              </tr>
            </thead>
            <tbody>
              {items.map((item, index) => (
                <tr key={index}>
                  <td>
                    <ItemNameInput
                      index={index}
                      value={item.name}
                      onChange={(val) => {
                        const updated = [...items]; updated[index].name = val; setItems(updated);
                      }}
                      onSelectInventory={(invItem) => {
                        const updated = [...items]; updated[index].name = invItem.name; updated[index].price = invItem.sellingPrice; setItems(updated);
                      }}
                    />
                  </td>
                  <td>
                    <input type="number" className="legacy-input" style={{ width: '100%' }} min="1"
                      value={item.quantity} onChange={(e) => { const updated = [...items]; updated[index].quantity = parseInt(e.target.value)||0; setItems(updated); }} />
                  </td>
                  <td>
                    <input type="number" className="legacy-input" style={{ width: '100%' }} min="0" step="0.01"
                      value={item.price||""} onChange={(e) => { const updated = [...items]; updated[index].price = parseFloat(e.target.value)||0; setItems(updated); }} />
                  </td>
                  <td style={{ textAlign: 'right' }}>
                    {(item.quantity * item.price).toFixed(2)}
                  </td>
                  <td>
                    <button type="button" className="legacy-button" style={{ padding: '0 4px' }} disabled={items.length === 1}
                      onClick={() => setItems(items.filter((_, i) => i !== index))}>X</button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
          <button type="button" className="legacy-button" style={{ marginTop: '4px' }} onClick={() => setItems([...items, { name: "", quantity: 1, price: 0 }])}>
            + Add Item
          </button>
        </div>

        {/* Summary & Payment */}
        <div className="legacy-fieldset">
          <div className="legacy-legend">Summary & Payment</div>
          <div style={{ display: 'flex', gap: '20px' }}>
            {/* Left side calculations */}
            <div style={{ flex: 1, display: 'flex', flexDirection: 'column', gap: '4px' }}>
              <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                <label>Discount:</label>
                <input type="number" className="legacy-input" style={{ width: '60px', textAlign: 'right' }} value={discount||""} onChange={(e) => setDiscount(parseFloat(e.target.value)||0)} />
              </div>
              <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                <label>GST (%):</label>
                <input type="number" className="legacy-input" style={{ width: '60px', textAlign: 'right' }} value={gst||""} onChange={(e) => setGst(parseFloat(e.target.value)||0)} />
              </div>
              <div style={{ display: 'flex', justifyContent: 'space-between', borderTop: '1px solid #808080', paddingTop: '2px', fontWeight: 'bold' }}>
                <label>Grand Total:</label>
                <span>{formatCurrency(total)}</span>
              </div>
            </div>

            {/* Right side payment status */}
            <div style={{ flex: 1, display: 'flex', flexDirection: 'column', gap: '4px' }}>
              <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                <label>Mode:</label>
                <select className="legacy-input" value={paymentMode} onChange={(e) => setPaymentMode(e.target.value)}>
                  <option value="CASH">Cash</option><option value="UPI">UPI</option><option value="CARD">Card</option>
                </select>
              </div>
              <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                <label>Status:</label>
                <select className="legacy-input" value={paymentStatus} onChange={(e) => { setPaymentStatus(e.target.value); if(e.target.value !== "PARTIAL") setAmountPaid(""); }}>
                  <option value="PAID">Paid</option><option value="UNPAID">Unpaid</option><option value="PARTIAL">Partial</option>
                </select>
              </div>
              {paymentStatus === "PARTIAL" && (
                <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                  <label>Paid Amt:</label>
                  <input type="number" className="legacy-input" style={{ width: '60px', textAlign: 'right' }} value={amountPaid} onChange={(e) => setAmountPaid(e.target.value===""?"":parseFloat(e.target.value))} />
                </div>
              )}
            </div>
          </div>
          </div>

          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '8px' }}>
            <div>
              <label className="label">Document Type</label>
              <select className="legacy-input w-full" value={type} onChange={(e) => setType(e.target.value)}>
                <option value="INVOICE">Tax Invoice</option>
                <option value="QUOTATION">Quotation / Proforma</option>
              </select>
            </div>
            {type === "INVOICE" && (
              <div>
                <label className="label">Due Date (For Late Fees)</label>
                <input 
                  type="date" 
                  className="legacy-input w-full" 
                  value={dueDate} 
                  onChange={(e) => setDueDate(e.target.value)} 
                />
              </div>
            )}
          </div>

        {/* Buttons */}
        <div style={{ display: 'flex', justifyContent: 'space-between', marginTop: '4px' }}>
          <button type="submit" className="legacy-button" disabled={loading} style={{ width: '100px', fontWeight: 'bold' }}>
            <span style={{ color: 'green', marginRight: '4px' }}>✓</span> {loading ? 'Saving...' : 'OK'}
          </button>
          <button type="button" className="legacy-button" onClick={onClose} style={{ width: '100px' }}>
            <span style={{ color: 'red', marginRight: '4px' }}>⊗</span> Cancel
          </button>
        </div>

      </form>
    </LegacyDialog>

    <AddCustomerDialog
      isOpen={isAddCustomerOpen}
      onClose={() => setIsAddCustomerOpen(false)}
      initialSearch={customerSearch}
      onSuccess={(newCust) => {
        if (newCust) {
          setSelectedCustomer(newCust);
          setCustomerSearch("");
          setCustomers([]);
        }
      }}
      zIndex={10050}
    />
    </>
  );
}

import React, { useState } from 'react';
import LegacyDialog from '@/components/layout/LegacyDialog';
import { useToast } from '@/contexts/ToastContext';

interface AddCustomerDialogProps {
  isOpen: boolean;
  onClose: () => void;
  onSuccess?: (customer?: any) => void;
  zIndex?: number;
  initialSearch?: string;
}

export default function AddCustomerDialog({ isOpen, onClose, onSuccess, zIndex, initialSearch }: AddCustomerDialogProps) {
  const toast = useToast();
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [formData, setFormData] = useState({
    name: '',
    mobile: '',
    email: '',
    address: '',
    aadhaarNumber: '',
    panNumber: ''
  });

  // Pre-fill initial input if provided when opened
  React.useEffect(() => {
    if (isOpen) {
      const search = initialSearch?.trim() || '';
      const isMobile = /^[0-9]{1,10}$/.test(search);
      setFormData({
        name: isMobile ? '' : search,
        mobile: isMobile ? search : '',
        email: '',
        address: '',
        aadhaarNumber: '',
        panNumber: ''
      });
    }
  }, [isOpen, initialSearch]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);

    try {
      const response = await fetch('/api/customers', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(formData),
      });

      if (!response.ok) {
        const errorText = await response.text();
        let errorMsg = 'Failed to create customer';
        try {
          const json = JSON.parse(errorText);
          if (json.error) errorMsg = json.error;
        } catch {}
        throw new Error(errorMsg);
      }

      const createdCustomer = await response.json();
      toast.success('Customer created successfully');
      setFormData({ name: '', mobile: '', email: '', address: '', aadhaarNumber: '', panNumber: '' });
      if (onSuccess) onSuccess(createdCustomer);
      onClose();
    } catch (error: any) {
      toast.error(error.message || 'Something went wrong');
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <LegacyDialog isOpen={isOpen} onClose={onClose} title="Add New Customer" width="450px" zIndex={zIndex}>
      <form onSubmit={handleSubmit} style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>

        {/* Customer Details Fieldset */}
        <div className="legacy-fieldset" style={{ marginTop: '12px' }}>
          <div className="legacy-legend">Customer Details</div>

          <div style={{ display: 'flex', flexDirection: 'column', gap: '6px', marginTop: '8px' }}>
            <div style={{ display: 'flex', alignItems: 'center' }}>
              <label style={{ width: '120px' }}>Full Name *:</label>
              <input 
                type="text" 
                required 
                className="legacy-input" 
                style={{ flex: 1 }}
                value={formData.name}
                onChange={(e) => setFormData({...formData, name: e.target.value})}
              />
            </div>

            <div style={{ display: 'flex', alignItems: 'center' }}>
              <label style={{ width: '120px' }}>Mobile Number *:</label>
              <input 
                type="text" 
                required 
                pattern="[0-9]{10}"
                title="10 digit mobile number"
                className="legacy-input" 
                style={{ flex: 1 }}
                value={formData.mobile}
                onChange={(e) => setFormData({...formData, mobile: e.target.value})}
              />
            </div>

            <div style={{ display: 'flex', alignItems: 'center' }}>
              <label style={{ width: '120px' }}>Email Address:</label>
              <input 
                type="email" 
                className="legacy-input" 
                style={{ flex: 1 }}
                value={formData.email}
                onChange={(e) => setFormData({...formData, email: e.target.value})}
              />
            </div>

            <div style={{ display: 'flex', alignItems: 'flex-start' }}>
              <label style={{ width: '120px', marginTop: '2px' }}>Address:</label>
              <textarea 
                className="legacy-input" 
                style={{ flex: 1, height: '40px', resize: 'none' }}
                value={formData.address}
                onChange={(e) => setFormData({...formData, address: e.target.value})}
              />
            </div>
          </div>
        </div>

        {/* Identity Fieldset */}
        <div className="legacy-fieldset" style={{ marginTop: '4px' }}>
          <div className="legacy-legend">Identity Documents</div>

          <div style={{ display: 'flex', flexDirection: 'column', gap: '6px', marginTop: '8px' }}>
            <div style={{ display: 'flex', alignItems: 'center' }}>
              <label style={{ width: '120px' }}>Aadhaar Number:</label>
              <input 
                type="text" 
                pattern="[0-9]{12}"
                title="12 digit Aadhaar number"
                className="legacy-input" 
                style={{ flex: 1 }}
                value={formData.aadhaarNumber}
                onChange={(e) => setFormData({...formData, aadhaarNumber: e.target.value})}
              />
            </div>

            <div style={{ display: 'flex', alignItems: 'center' }}>
              <label style={{ width: '120px' }}>PAN Number:</label>
              <input 
                type="text" 
                pattern="[A-Z]{5}[0-9]{4}[A-Z]{1}"
                title="Valid PAN format (e.g. ABCDE1234F)"
                style={{ textTransform: 'uppercase', flex: 1 }}
                className="legacy-input" 
                value={formData.panNumber}
                onChange={(e) => setFormData({...formData, panNumber: e.target.value.toUpperCase()})}
              />
            </div>
          </div>
        </div>

        {/* Action Buttons */}
        <div style={{ display: 'flex', justifyContent: 'flex-start', gap: '8px', marginTop: '8px' }}>
          <button type="submit" className="legacy-button" disabled={isSubmitting} style={{ width: '80px' }}>
            <span style={{ color: 'green' }}>✓</span> {isSubmitting ? 'Wait...' : 'OK'}
          </button>
          <button type="button" className="legacy-button" onClick={() => setFormData({name: '', mobile: '', email: '', address: '', aadhaarNumber: '', panNumber: ''})} style={{ width: '80px' }}>
            <span style={{ color: 'red' }}>⊗</span> Clear
          </button>
          <button type="button" className="legacy-button" onClick={onClose} style={{ marginLeft: 'auto', width: '80px' }}>
            Cancel
          </button>
        </div>

      </form>
    </LegacyDialog>
  );
}

"use client";

import { useState, useEffect, useRef } from "react";
import { Search, Menu, Bell, AlertTriangle, Clock, MessageCircle, Mail, FolderOpen, Sparkles, LogOut, X, Key } from "lucide-react";
import { useWorkspace } from "@/components/workspace/WorkspaceProvider";
import AIAssistant from "@/components/ai/AIAssistant";
import { signOut } from "next-auth/react";

interface HeaderProps {
  onMenuToggle: () => void;
  pageTitle?: string;
}

export default function Header({ onMenuToggle, pageTitle }: HeaderProps) {
  const { openSearch } = useWorkspace();
  const [showNotifications, setShowNotifications] = useState(false);
  const [showAI, setShowAI] = useState(false);
  const [showLogoutConfirm, setShowLogoutConfirm] = useState(false);
  const [notifications, setNotifications] = useState<{
    pendingServices: any[];
    lowStockItems: any[];
  }>({ pendingServices: [], lowStockItems: [] });

  const notifRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const openWhatsApp = () => {
    window.open("https://web.whatsapp.com/", "_blank");
  };

  const openMail = () => {
    window.open("https://mail.google.com/", "_blank");
  };

  const openFileExplorer = () => {
    if (fileInputRef.current) {
      fileInputRef.current.click();
    }
  };

  useEffect(() => {
    fetch("/api/notifications")
      .then((res) => res.json())
      .then((data) => {
        if (data && !data.error) {
          setNotifications(data);
        }
      })
      .catch(() => {});
  }, []);

  useEffect(() => {
    const handler = (e: MouseEvent) => {
      if (notifRef.current && !notifRef.current.contains(e.target as Node)) {
        setShowNotifications(false);
      }
    };
    document.addEventListener("mousedown", handler);
    return () => document.removeEventListener("mousedown", handler);
  }, []);

  const totalNotifs =
    notifications.pendingServices.length + notifications.lowStockItems.length;

  return (
    <header className="app-header">
      <div className="app-header-left">
        <button className="header-icon-button lg:hidden" onClick={onMenuToggle} title="Open navigation">
          <Menu size={18} />
        </button>

        {pageTitle && (
          <div className="header-title hidden sm:flex">
            <div className="header-title-accent" />
            <h1>{pageTitle}</h1>
          </div>
        )}
      </div>

      <div className="flex items-center justify-center gap-2 md:gap-4 px-2" style={{ zIndex: 10 }}>
        <div 
          className="hidden md:flex items-center" 
          style={{ border: '2px inset #dfdfdf', background: '#fff', height: '26px', width: '200px' }}
        >
          <input 
            type="text" 
            placeholder="Search..." 
            style={{ flex: 1, paddingLeft: '6px', fontSize: '13px', border: 'none', outline: 'none', background: 'transparent' }}
            onFocus={openSearch}
          />
          <button 
            className="legacy-button" 
            style={{ height: '20px', width: '22px', padding: 0, display: 'flex', alignItems: 'center', justifyContent: 'center', marginRight: '1px' }}
            title="Search"
            onClick={openSearch}
          >
            <Search size={14} color="#000" />
          </button>
        </div>

        <div className="flex items-center gap-1 sm:gap-2">
          <input type="file" ref={fileInputRef} className="hidden" />

          <button className="legacy-button" style={{ padding: '4px 8px', color: '#000' }} onClick={openFileExplorer} title="Open File Explorer">
            <FolderOpen size={16} />
          </button>

          <div className="relative" ref={notifRef}>
            <button
              className="legacy-button relative"
              style={{ padding: '4px 8px', color: '#eab308' }}
              title="Notifications"
              onClick={() => setShowNotifications(!showNotifications)}
            >
              <Bell size={16} />
              {totalNotifs > 0 && (
                <span
                  className="absolute top-0 right-0 flex items-center justify-center text-[9px] font-bold text-white rounded-full min-w-[14px] h-[14px] px-0.5"
                  style={{
                    background: "linear-gradient(135deg, #f43f5e, #e11d48)",
                    boxShadow: "0 0 6px rgba(244,63,94,0.6)",
                    transform: "translate(25%, -25%)"
                  }}
                >
                  {totalNotifs > 9 ? "9+" : totalNotifs}
                </span>
              )}
            </button>
          {/* Notifications Dropdown */}
          {showNotifications && (
            <div
              className="absolute top-full mt-2 -right-2 md:right-0 w-80 rounded-xl border shadow-xl z-50 overflow-hidden flex flex-col max-h-[85vh]"
              style={{
                background: "var(--bg-primary)",
                borderColor: "var(--border-primary)",
                boxShadow: "var(--shadow-lg)",
              }}
            >
              <div className="p-3 border-b" style={{ borderColor: "var(--border-secondary)", background: "var(--bg-secondary)" }}>
                <h3 className="text-sm font-semibold" style={{ color: "var(--text-primary)" }}>
                  Notifications
                </h3>
              </div>

              <div className="overflow-y-auto flex-1 p-2 space-y-1 text-left">
                {totalNotifs === 0 ? (
                  <div className="p-4 text-center text-sm" style={{ color: "var(--text-muted)" }}>
                    All caught up! No new notifications.
                  </div>
                ) : (
                  <>
                    {notifications.pendingServices.length > 0 && (
                      <div className="mb-3">
                        <div className="px-2 py-1 text-xs font-semibold uppercase tracking-wider mb-1" style={{ color: "var(--brand-primary)" }}>
                          Pending Services
                        </div>
                        {notifications.pendingServices.map((srv) => (
                          <div key={srv.id} className="p-2 rounded-lg hover:bg-[var(--bg-tertiary)] transition-colors mb-1 cursor-default">
                            <div className="flex items-start gap-2">
                              <Clock size={14} className="text-orange-500 mt-0.5 shrink-0" />
                              <div>
                                <div className="text-sm font-medium leading-tight" style={{ color: "var(--text-primary)" }}>
                                  {srv.customer?.name} - {srv.serviceType}
                                </div>
                                <div className="text-xs mt-0.5" style={{ color: "var(--text-muted)" }}>
                                  Since {new Date(srv.createdAt).toLocaleDateString()}
                                </div>
                              </div>
                            </div>
                          </div>
                        ))}
                      </div>
                    )}

                    {notifications.lowStockItems.length > 0 && (
                      <div>
                        <div className="px-2 py-1 text-xs font-semibold uppercase tracking-wider mb-1 text-red-500">
                          Low Stock Alert
                        </div>
                        {notifications.lowStockItems.map((item) => (
                          <div key={item.id} className="p-2 rounded-lg hover:bg-[var(--bg-tertiary)] transition-colors mb-1 cursor-default">
                            <div className="flex items-start gap-2">
                              <AlertTriangle size={14} className="text-red-500 mt-0.5 shrink-0" />
                              <div>
                                <div className="text-sm font-medium leading-tight" style={{ color: "var(--text-primary)" }}>
                                  {item.name}
                                </div>
                                <div className="text-xs mt-0.5" style={{ color: "var(--text-muted)" }}>
                                  Only {item.quantity} left (Min: {item.minStock})
                                </div>
                              </div>
                            </div>
                          </div>
                        ))}
                      </div>
                    )}
                  </>
                )}
              </div>
            </div>
          )}
          </div>

          <a href="https://web.whatsapp.com/" target="_blank" rel="noopener noreferrer" className="legacy-button" style={{ padding: '4px 8px', color: '#25D366', display: 'flex' }} title="WhatsApp Web">
            <MessageCircle size={16} />
          </a>

          <a href="https://mail.google.com/" target="_blank" rel="noopener noreferrer" className="legacy-button" style={{ padding: '4px 8px', color: '#ef4444', display: 'flex' }} title="Open Mail">
            <Mail size={16} />
          </a>

          <button 
            className="legacy-button" 
            style={{ padding: '4px 8px', color: '#3b82f6' }}
            onClick={() => setShowAI(true)} 
            title="RA Seva AI Assistant"
          >
            <Sparkles size={16} />
          </button>
        </div>
      </div>

      {/* Empty right div to keep grid balance if app-header grid relies on 3 columns */}
      <div className="app-header-right" style={{ display: 'flex', justifyContent: 'flex-end', paddingRight: '4px' }}>
        <button 
          className="legacy-button" 
          style={{ padding: '2px 8px', display: 'flex', alignItems: 'center', gap: '4px', fontWeight: 'bold', color: '#000' }}
          onClick={() => setShowLogoutConfirm(true)}
          title="Log Off"
        >
          <LogOut size={14} /> Log Off
        </button>
      </div>

      {/* AI Assistant Modal */}
      <AIAssistant isOpen={showAI} onClose={() => setShowAI(false)} />

      {/* Logout Confirmation */}
      {showLogoutConfirm && (
        <div style={{
          position: 'fixed', top: 0, left: 0, right: 0, bottom: 0,
          backgroundColor: 'transparent', zIndex: 9999,
          display: 'flex', alignItems: 'center', justifyContent: 'center'
        }}>
          <div style={{
              width: '350px',
              backgroundColor: '#d4d0c8',
              borderTop: '2px solid #fff',
              borderLeft: '2px solid #fff',
              borderRight: '2px solid #404040',
              borderBottom: '2px solid #404040',
              boxShadow: '1px 1px 4px rgba(0,0,0,0.5)',
              display: 'flex',
              flexDirection: 'column',
              fontSize: '11px',
              color: 'black'
          }}>
            <div style={{
                background: 'linear-gradient(to right, #0a246a 0%, #a6caf0 100%)',
                color: 'white',
                fontWeight: 'bold',
                padding: '3px 2px 3px 4px',
                display: 'flex',
                justifyContent: 'space-between',
                alignItems: 'center',
                userSelect: 'none',
                margin: '2px'
            }}>
              <div style={{ display: 'flex', alignItems: 'center', gap: '4px' }}>
                <Key size={14} color="#ffd700" style={{ filter: 'drop-shadow(1px 1px 1px #000)' }} />
                Log Off Windows
              </div>
              <button className="legacy-btn-close" type="button" onClick={() => setShowLogoutConfirm(false)} title="Close">
                <X size={12} strokeWidth={3} />
              </button>
            </div>
            <div style={{ padding: '16px', display: 'flex', gap: '16px' }}>
              <div style={{ width: '48px', display: 'flex', justifyContent: 'center' }}>
                <div style={{ width: '32px', height: '32px', background: 'linear-gradient(135deg, #008080, #004040)', border: '2px solid #fff', borderRadius: '4px', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                  <Key size={20} color="#ffd700" />
                </div>
              </div>
              <div style={{ flex: 1, display: 'flex', flexDirection: 'column', justifyContent: 'center' }}>
                <p style={{ margin: '0 0 16px 0', fontSize: '11px' }}>Are you sure you want to log off?</p>
                <div style={{ display: 'flex', justifyContent: 'flex-end', gap: '8px' }}>
                  <button className="legacy-button" style={{ width: '70px', fontWeight: 'bold' }} onClick={() => signOut({ callbackUrl: '/login' })}>
                    Yes
                  </button>
                  <button className="legacy-button" style={{ width: '70px' }} onClick={() => setShowLogoutConfirm(false)}>
                    No
                  </button>
                </div>
              </div>
            </div>
          </div>
        </div>
      )}
    </header>
  );
}

